/* KHBD Tin học Lớp 3 KNTT — soạn cho Bút Xanh, tích hợp Năng lực số + AI */
window.KHO_DATA_L3_TINHOC = [
{"lop":3,"mon":"Tin học","tuan":1,"tiet":1,"bai":"Bài 1: Thông tin và quyết định (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được ví dụ đơn giản minh hoạ vai trò của thông tin thu nhận hằng ngày đối với việc đưa ra quyết định của con người.\n- Nhận biết được thông tin và quyết định trong ví dụ cụ thể.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.2 CB1a: Phát hiện được độ tin cậy và độ chính xác của các nguồn chung của dữ liệu, thông tin và nội dung số: HS nêu được vì sao phải lấy thông tin từ nguồn đáng tin trước khi quyết định.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: khi nghe tiếng chuông đồng hồ báo thức buổi sáng, bạn Minh sẽ quyết định làm gì?\n- Cho HS thảo luận, báo cáo; GV nhận xét, dẫn vào bài.","hs":"- HS thảo luận, trả lời: nghe chuông → thức dậy, vệ sinh cá nhân, ăn sáng, đi học.\n- Lắng nghe, nhận ra tiếng chuông là thông tin giúp Minh quyết định."},{"ten":"2. Khám phá: Thông tin và quyết định","gv":"- GV tổ chức nhóm tìm hiểu tình huống trong SGK: điều bạn nhận biết là thông tin, việc bạn chọn làm là quyết định.\n- Chốt: thông tin giúp con người đưa ra quyết định.","hs":"- HS thảo luận, phân biệt câu nào là thông tin, câu nào là quyết định (VD SGK tr.6).\n- Ghi nhớ nội dung hộp kiến thức."},{"ten":"3. Khám phá: Vai trò của thông tin","gv":"- GV nêu ví dụ: biết hôm nay có tiết Giáo dục thể chất → quyết định mang giày thể thao.\n- Cho HS nêu thêm ví dụ; chốt vai trò của thông tin.","hs":"- HS nêu ví dụ của bản thân: có thông tin gì → đưa ra quyết định gì.\n- Trình bày, nhận xét nhóm bạn."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập phân biệt thông tin/quyết định (SGK tr.8).","hs":"- HS làm bài, chữa bài, giải thích lựa chọn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu các tình huống quen thuộc: đèn giao thông chuyển màu, trống báo giờ vào lớp, bản tin dự báo thời tiết trên điện thoại; với mỗi tình huống HS nói rõ em nhận được thông tin gì và sau đó em quyết định làm việc gì. GV thao tác thiết bị, HS quan sát và trả lời.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở bản tin thời tiết hôm nay trên trang chính thống của cơ quan khí tượng rồi hỏi: với thông tin này, mai đi học em mặc áo gì, mang theo gì? HS thấy rõ thông tin đúng dẫn tới quyết định đúng, còn nghe theo lời đồn thì quyết định sai.\n⚠ (Miền 4: An toàn) Thông tin về thời tiết, giờ giấc phải xem ở trang hoặc ứng dụng chính thức chứ không nghe theo lời đồn; HS chưa tự cầm điện thoại, máy tính của GV mà chỉ quan sát; thấy trên màn hình có gì lạ phải nói ngay với thầy cô.","hs":"- HS chỉ ra được trong mỗi tình huống em nhận thông tin gì và ra quyết định gì.\n- HS nêu được vì sao phải lấy thông tin từ nguồn đáng tin trước khi quyết định."}]},
{"lop":3,"mon":"Tin học","tuan":2,"tiet":2,"bai":"Bài 1: Thông tin và quyết định (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được ba dạng thông tin thường gặp: chữ, hình ảnh, âm thanh.\n- Vận dụng phân loại được dạng thông tin trong tình huống quen thuộc.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nhận ra ba dạng thông tin chữ, hình ảnh, âm thanh mà máy tính lưu giữ được.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS kể những gì nhìn thấy, nghe thấy trên đường đến trường.","hs":"- HS kể: biển tên trường (chữ), tranh cổ động (hình ảnh), tiếng chim hót (âm thanh)."},{"ten":"2. Khám phá: Ba dạng thông tin","gv":"- GV tổ chức nhóm nhận biết ba dạng thông tin qua hình SGK.\n- Chốt: thông tin thường gặp ở dạng chữ, hình ảnh, âm thanh.","hs":"- HS thảo luận, phân loại thông tin theo ba dạng; ghi nhớ hộp kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS làm bài tập nhận dạng thông tin trên thùng rác phân loại, biển báo... (SGK).","hs":"- HS làm bài, xác định dạng thông tin (chữ/hình ảnh/âm thanh)."},{"ten":"4. Vận dụng","gv":"- GV giao: hãy mô tả một việc em định làm sau khi tan học và cho biết thông tin nào giúp em quyết định.","hs":"- HS thực hiện ngoài giờ, chia sẻ ở tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV lần lượt mở trên máy tính một tệp chữ, một tấm ảnh và một đoạn âm thanh về cùng một con vật; HS nhận ra máy tính giữ được cả ba dạng thông tin là chữ, hình ảnh, âm thanh và nói dạng nào giúp em nhận ra con vật đó nhanh nhất.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho HS xem máy tính đọc một câu chữ thành tiếng, rồi nói một câu để máy chuyển thành chữ hiện lên màn hình; GV nói rõ đó là phần mềm thông minh do con người làm ra, máy vẫn nghe nhầm và viết sai nên phải đọc lại mà sửa. HS chỉ quan sát, chưa tự thao tác.\n⚠ (Miền 4: An toàn) HS quan sát GV thao tác, không nói họ tên đầy đủ, địa chỉ nhà hay tên trường vào micrô của máy; chỉ mở những tệp GV đã chuẩn bị sẵn; ngồi cách màn hình vừa tầm mắt, mở loa vừa đủ nghe.","hs":"- HS nhận ra ba dạng thông tin chữ, hình ảnh, âm thanh mà máy tính lưu giữ được.\n- HS nêu được máy có thể nghe nhầm, viết sai nên người phải đọc lại và sửa."}]},
{"lop":3,"mon":"Tin học","tuan":3,"tiet":3,"bai":"Bài 2: Xử lí thông tin (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được quá trình thu nhận và xử lí thông tin.\n- Nêu được ví dụ minh hoạ bộ não con người là bộ phận xử lí thông tin.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS đặt đúng một việc quen thuộc vào sơ đồ Thu nhận – Xử lí – Kết quả.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV mở một đoạn video ngắn bài hát quen thuộc có phụ đề, cho cả lớp hát theo, sau đó hỏi: khi hát theo, tai em làm gì, mắt em làm gì?\n- GV hỏi tiếp: nếu bịt tai lại thì em còn hát đúng nhịp được không, vì sao?\n- GV ghi nhanh ý kiến lên bảng thành hai cột: bộ phận nhận tin và bộ phận suy nghĩ, rồi dẫn vào bài.","hs":"- HS hát theo và trả lời: tai nghe nhạc, mắt nhìn lời bài hát hiện trên màn hình.\n- HS nêu: bịt tai thì không nghe được nhạc nên hát sai nhịp, hát chậm hơn.\n- HS nhận ra tai và mắt thu nhận thông tin, bộ não suy nghĩ rồi điều khiển miệng hát."},{"ten":"2. Khám phá: Con người xử lí thông tin","gv":"- (12 phút) GV chiếu hình trong SGK, chia lớp thành nhóm 4, phát phiếu học tập kẻ ba cột: Thu nhận - Xử lí - Kết quả.\n- GV nêu câu hỏi: bạn nhỏ trong hình nhận được thông tin gì, bộ phận nào giúp bạn suy nghĩ và quyết định?\n- Dự kiến HS trả lời: bạn nhìn thấy đèn đỏ, bộ não suy nghĩ, kết quả là bạn dừng xe lại.\n- GV chốt: bộ não là bộ phận xử lí thông tin, tạo ra quyết định và điều khiển hành động; cho HS đọc hộp kiến thức.","hs":"- HS làm việc nhóm 4, điền phiếu ba cột theo hình trong SGK.\n- HS trả lời: thông tin được thu nhận qua tai, mắt, mũi, lưỡi, da; bộ não làm nhiệm vụ xử lí.\n- HS đọc và ghi nhớ hộp kiến thức: bộ não là bộ phận xử lí thông tin của con người."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV cho HS làm bài tập trong SGK: chỉ ra bộ phận xử lí thông tin của con người.\n- GV nêu ví dụ bạn nhỏ thả diều: em thu nhận thông tin gì, xử lí ra sao, kết quả là gì?\n- GV tổ chức trò chơi Ai nhanh hơn: chiếu ba tình huống, HS giơ thẻ Đ hoặc S để chọn câu nói đúng về việc xử lí thông tin.","hs":"- HS làm bài, khoanh đáp án và giải thích lựa chọn của mình.\n- HS trả lời: mắt nhìn diều bay, tay cảm nhận dây căng hay chùng, bộ não xử lí rồi quyết định thả thêm dây hay thu dây lại.\n- HS giơ thẻ Đ hoặc S, nhận xét bài của bạn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao nhiệm vụ: hãy nêu một việc em làm hằng ngày, cho biết em thu nhận thông tin gì và kết quả xử lí là gì.\n- GV gợi ý mẫu: nghe trống báo hết giờ ra chơi thì xếp hàng vào lớp.\n- GV nhận xét, tuyên dương; dặn HS chuẩn bị bài tiết sau, xem trước phần máy tính xử lí thông tin và giữ gìn sách vở, đồ dùng.","hs":"- HS suy nghĩ, ghi câu trả lời vào vở rồi chia sẻ trước lớp.\n- HS nêu ví dụ: thấy trời tối thì bật đèn học, nghe mẹ gọi thì dạ và đi ra.\n- HS lắng nghe dặn dò, ghi việc cần chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu sơ đồ động Thu nhận → Xử lí → Kết quả, hiện dần từng ô; HS đặt vài việc quen thuộc vào sơ đồ: nghe trống báo hết giờ thì xếp sách vở, thấy đèn đỏ thì dừng lại. Sơ đồ hiện từng bước giúp HS nhìn ra chỗ nào là phần suy nghĩ, xử lí.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu ba nguồn thông tin cho cùng một việc đi tham quan: một tấm phiếu ghi giờ tập trung, một biển báo chỉ đường, một bản tin thời tiết; HS nói mỗi nguồn cho em biết điều gì và thiếu nguồn nào thì em không đi được.\n⚠ (Miền 4: An toàn) Chỉ dùng những phiếu, biển báo, bản tin GV đã chuẩn bị; thông tin nghe được từ người khác phải hỏi lại thầy cô, cha mẹ trước khi tin; không tự chạm vào máy chiếu và máy tính của GV.","hs":"- HS đặt đúng một việc quen thuộc vào sơ đồ Thu nhận – Xử lí – Kết quả.\n- HS nêu được mỗi nguồn thông tin cho em biết điều gì."}]},
{"lop":3,"mon":"Tin học","tuan":4,"tiet":4,"bai":"Bài 2: Xử lí thông tin (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được ví dụ cho thấy máy móc cũng tiếp nhận thông tin và quyết định hành động.\n- Nhận biết được máy móc xử lí thông tin gì và kết quả ra sao.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS kể được thiết bị quanh mình nhận thông tin rồi tự thực hiện công việc.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS kể tên thiết bị điện trong gia đình điều khiển được (ti vi, máy giặt, điều hoà...).","hs":"- HS kể tên thiết bị và nêu cách điều khiển bằng nút bấm, điều khiển từ xa."},{"ten":"2. Khám phá: Máy xử lí thông tin","gv":"- GV tổ chức nhóm tìm hiểu: con người cung cấp thông tin cho thiết bị, thiết bị xử lí và thực hiện.\n- Chốt: nhiều thiết bị tiếp nhận thông tin để quyết định hành động.","hs":"- HS thảo luận: ví dụ nhấn nút + của bếp từ → bếp nhận thông tin tăng nhiệt → thực hiện; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS ghép cặp thông tin – hành động của máy; giải thích ví dụ bếp từ (SGK).","hs":"- HS làm bài, trình bày."},{"ten":"4. Vận dụng","gv":"- GV: hãy nêu một thiết bị ở nhà em nhận thông tin để hành động và mô tả cách hoạt động.","hs":"- HS thực hiện, chia sẻ tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim ngắn: máy giặt nhận lệnh rồi tự chạy, cửa siêu thị tự mở khi có người tới gần, đèn đường tự sáng khi trời tối; HS chỉ ra trong mỗi trường hợp máy đã nhận thông tin gì và làm việc gì sau đó.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV nói một câu lệnh đơn giản vào loa thông minh hoặc điện thoại cho cả lớp xem máy trả lời; GV giải thích máy nghe hiểu được là nhờ phần mềm con người dạy cho nó, và máy vẫn trả lời sai khi nghe không rõ. HS quan sát và nhận xét, chưa tự ra lệnh cho máy.\n⚠ (Miền 4: An toàn) Không nói họ tên đầy đủ, địa chỉ nhà, số điện thoại của gia đình vào các thiết bị nghe được tiếng nói; ở nhà chỉ dùng loa thông minh, điện thoại khi có người lớn bên cạnh; máy trả lời gì cũng phải hỏi lại người lớn cho chắc.","hs":"- HS kể được thiết bị quanh mình nhận thông tin rồi tự thực hiện công việc.\n- HS nêu được máy nghe hiểu nhờ phần mềm con người tạo ra và máy vẫn có thể sai."}]},
{"lop":3,"mon":"Tin học","tuan":5,"tiet":5,"bai":"Bài 3: Máy tính và em (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận diện, phân biệt được hình dạng thường gặp của máy tính thông dụng và các bộ phận cơ bản: màn hình, thân máy, bàn phím, chuột.\n- Nêu được sơ lược chức năng của các bộ phận đó.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS gọi đúng tên các bộ phận của máy tính và nêu việc của từng bộ phận.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi Ai nhanh – Ai đúng: kể tên các bộ phận của máy tính để bàn.","hs":"- HS tham gia, nêu được 4 bộ phận chính: thân máy, màn hình, bàn phím, chuột."},{"ten":"2. Khám phá: Các bộ phận cơ bản","gv":"- GV cho HS quan sát máy tính thật/hình, chỉ và gọi tên bộ phận; gắn thẻ tên.\n- Chốt chức năng: thân máy (xử lí), màn hình (hiển thị), bàn phím (nhập), chuột (điều khiển), loa (âm thanh).","hs":"- HS hoạt động nhóm, chỉ và nói tên bộ phận; gắn thẻ; ghi nhớ hộp kiến thức."},{"ten":"3. Khám phá: Một số loại máy tính khác","gv":"- GV giới thiệu máy tính xách tay, máy tính bảng, điện thoại thông minh; màn hình cảm ứng là thiết bị nhập.","hs":"- HS nhận biết các loại máy tính; hiểu màn hình cảm ứng thay chức năng chuột và bàn phím."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập chọn bộ phận cơ bản, bộ phận nhập thông tin (SGK tr.14-15).","hs":"- HS làm bài, chữa bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV cho HS đứng quanh một bộ máy tính thật, chỉ và gọi tên từng bộ phận: thân máy, màn hình, bàn phím, chuột, loa; sau đó chiếu ảnh máy tính xách tay và máy tính bảng để HS nhận ra vẫn là những bộ phận ấy nhưng gộp lại thành một khối.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS chơi trò nối trên máy chiếu: nhìn ảnh một bộ phận, chọn đúng tên và đúng việc bộ phận đó làm — nhìn, gõ, trỏ, nghe; chọn sai thì máy báo ngay để HS chọn lại cho tới khi đúng.\n⚠ (Miền 4: An toàn) Không cắm, rút dây và không tháo bất cứ bộ phận nào khi máy đang bật; tay khô ráo mới chạm vào máy; thấy dây điện hở, máy có tiếng lạ hoặc nóng bất thường phải báo thầy cô ngay chứ không tự chạm vào.","hs":"- HS gọi đúng tên các bộ phận của máy tính và nêu việc của từng bộ phận.\n- HS nhận ra máy tính để bàn, máy tính xách tay, máy tính bảng đều có những bộ phận ấy."}]},
{"lop":3,"mon":"Tin học","tuan":6,"tiet":6,"bai":"Bài 3: Máy tính và em (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết và thực hiện được quy tắc an toàn về điện khi sử dụng máy tính.\n- Có ý thức đề phòng tai nạn về điện; nhận biết việc nên và không nên khi dùng máy tính.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS bật máy, mở phần mềm và tắt máy đúng cách theo hướng dẫn từng bước.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: phát hiện dây điện của máy tính bị hở, em sẽ làm gì?","hs":"- HS nêu cách xử lí an toàn: không tự chạm, báo thầy cô/người lớn."},{"ten":"2. Khám phá: An toàn về điện","gv":"- GV cho HS quan sát hình SGK, thảo luận việc nên/không nên để bảo đảm an toàn điện.\n- Chốt quy tắc an toàn về điện khi dùng máy tính.","hs":"- HS thảo luận, nêu việc nên làm (giữ tay khô, dùng đúng cách) và không nên (chạm dây hở, cắm nhiều thiết bị); ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS xử lí tình huống: dây chuột chưa cắm, có mùi khét từ dây điện... (SGK tr.17).","hs":"- HS chọn cách xử lí đúng: báo thầy cô, ra ngoài báo người lớn."},{"ten":"4. Vận dụng","gv":"- GV: máy tính không nghe được âm thanh thì cần lắp thêm thiết bị gì? Liên hệ an toàn điện ở nhà.","hs":"- HS trả lời (loa/tai nghe) và nêu cách dùng điện an toàn ở nhà."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV hướng dẫn HS làm theo từng bước: bật máy, chờ máy sẵn sàng, mở một phần mềm học tập, đóng phần mềm rồi tắt máy đúng cách; HS làm lại theo GV và nói được vì sao không được rút điện khi máy đang chạy.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS đọc các biểu tượng trên màn hình nền và nhận ra mỗi biểu tượng mở ra một phần mềm khác nhau; HS chỉ đúng biểu tượng GV yêu cầu rồi mới được nháy chuột vào đó.\n⚠ (Miền 4: An toàn) Chỉ mở phần mềm thầy cô cho phép; không tự xoá biểu tượng, không đổi hình nền, không cài thêm gì vào máy của trường; để đồ ăn thức uống xa máy; hết giờ tắt máy đúng cách rồi mới rời chỗ.","hs":"- HS bật máy, mở phần mềm và tắt máy đúng cách theo hướng dẫn từng bước.\n- HS nhận ra biểu tượng của phần mềm cần dùng trên màn hình nền."}]},
{"lop":3,"mon":"Tin học","tuan":7,"tiet":7,"bai":"Bài 4: Làm việc với máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết và ngồi đúng tư thế khi làm việc với máy tính, biết vị trí phù hợp của màn hình.\n- Nêu được tác hại của ngồi sai tư thế hoặc dùng máy tính quá thời gian quy định.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS ngồi đúng tư thế và giữ đúng khoảng cách với màn hình.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV chiếu tình huống bạn Khoa ngồi học với máy tính và nêu thắc mắc: tư thế ngồi thế nào là khoa học?\n- GV cho HS ngồi thử đúng tư thế mà các em vẫn ngồi ở nhà khi xem ti vi hoặc dùng máy tính.\n- GV hỏi: ngồi cúi sát màn hình lâu thì em thấy chỗ nào trên người mình mỏi?","hs":"- HS quan sát tình huống, nêu hiểu biết ban đầu về tư thế ngồi đúng.\n- HS ngồi thử tư thế quen thuộc của mình, quan sát bạn ngồi cạnh.\n- HS trả lời: mỏi cổ, mỏi lưng, cay mắt, nhức đầu."},{"ten":"2. Khám phá: Tư thế ngồi","gv":"- (12 phút) GV chiếu hình trong SGK, hướng dẫn HS quan sát từng chi tiết: lưng, mắt, hai tay và hai chân của bạn trong hình.\n- GV nêu câu hỏi: mắt cách màn hình bao xa là vừa, hai tay đặt thế nào, hai chân để ở đâu?\n- Dự kiến HS trả lời: mắt cách khoảng 50 đến 80 cm, tay ngang bàn phím, hai chân đặt trên sàn.\n- GV chốt: ngồi thẳng lưng, mắt ngang tầm và cách màn hình 50 đến 80 cm, tay ngang bàn phím, hai chân đặt trên sàn, phòng đủ ánh sáng và không để đèn chiếu thẳng vào màn hình.","hs":"- HS quan sát hình, thảo luận cặp đôi và chỉ ra từng chi tiết của tư thế đúng.\n- HS nêu tác hại của ngồi sai: vẹo cột sống, cận thị, mỏi mắt, mỏi tay.\n- HS đọc và ghi nhớ hộp kiến thức về tư thế ngồi đúng."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV cho HS làm bài tập trong SGK: chọn hình có tư thế ngồi đúng và nêu bệnh tránh được khi ngồi đúng.\n- GV tổ chức trò chơi Ngồi đẹp: GV hô Chuẩn bị, cả lớp ngồi đúng tư thế; GV đi từng bàn chỉnh lại ghế, tầm mắt cho HS.\n- Lỗi HS hay mắc và cách xử lí: ngồi vắt chéo chân hoặc quỳ trên ghế thì GV nhắc đặt cả hai bàn chân xuống sàn; cúi sát màn hình thì GV cho HS đo bằng một sải tay để tự giữ khoảng cách; tì cả cánh tay lên mép bàn thì GV hướng dẫn để cổ tay thẳng, khuỷu tay ngang mặt bàn.","hs":"- HS làm bài, chỉ ra hình đúng và giải thích vì sao hình còn lại là sai.\n- HS thực hành ngồi đúng tư thế tại chỗ, tự sửa theo hướng dẫn.\n- HS nhận ra lỗi của mình, đặt lại chân, chỉnh khoảng cách mắt và cổ tay cho đúng."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: về nhà em hãy sắp xếp lại góc học tập và luyện tư thế ngồi đúng khi học bài, khi dùng máy tính.\n- GV nhắc quy tắc giữ mắt: mỗi lần ngồi máy không quá 30 phút, cứ 20 phút thì nhìn ra xa cho mắt được nghỉ.\n- GV dặn chuẩn bị tiết sau học về chuột máy tính; nhắc HS không ăn uống cạnh máy và không tự ý rút dây điện.","hs":"- HS ghi nhớ nhiệm vụ, nêu cách kê lại bàn ghế và đèn học ở nhà.\n- HS nhắc lại quy tắc nghỉ mắt sau mỗi 20 phút nhìn màn hình.\n- HS lắng nghe dặn dò và ghi việc chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu ảnh hai bạn ngồi máy: một bạn cong lưng, mặt sát màn hình; một bạn ngồi thẳng, mắt cách màn hình khoảng 50 cm, hai chân đặt trên sàn. HS chỉ ra chỗ khác nhau rồi tự chỉnh lại ghế và khoảng cách ngồi của chính mình.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS đọc bảng khuyến cáo thời gian dùng máy tính theo lứa tuổi do GV chiếu lên, rồi cả lớp thống nhất quy tắc riêng: mỗi lần ngồi máy không quá 30 phút, cứ 20 phút thì nhìn ra xa cho đỡ mỏi mắt.\n⚠ (Miền 4: An toàn) Ngồi thẳng lưng, hai chân đặt trên sàn, mắt cách màn hình khoảng 50 cm; nghỉ mắt sau mỗi 20 phút; phòng phải đủ sáng, không dùng máy trong bóng tối; thấy mỏi mắt, nhức đầu phải nói với thầy cô ngay.","hs":"- HS ngồi đúng tư thế và giữ đúng khoảng cách với màn hình.\n- HS nêu và thực hiện được quy tắc về thời gian dùng máy của lớp."}]},
{"lop":3,"mon":"Tin học","tuan":8,"tiet":8,"bai":"Bài 4: Làm việc với máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết cầm chuột đúng cách và thực hiện được các thao tác cơ bản: di chuyển, nháy, nháy nút phải, nháy đúp, kéo thả chuột.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS làm được các thao tác chuột: di, nháy, nháy đúp, kéo thả.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV giơ một con chuột máy tính, cho HS chuyền tay quan sát và hỏi: chuột có mấy nút, nút nào ở bên trái, ở giữa có gì?\n- GV chia nhóm 2 đến 3 HS một máy, dán số nhóm lên máy và quy định luân phiên: mỗi bạn làm 3 phút rồi đổi lượt cho bạn.\n- GV nhắc nội quy phòng máy: không chạy nhảy, không ăn uống cạnh máy, không tự ý rút dây chuột và dây điện.","hs":"- HS quan sát, nêu: nút trái, nút phải và nút cuộn ở giữa.\n- HS về đúng máy theo nhóm, nhớ thứ tự lượt thực hành của mình.\n- HS nhắc lại nội quy phòng máy trước khi bắt đầu."},{"ten":"2. Khám phá: Chuột máy tính","gv":"- (8 phút) GV làm mẫu cách cầm chuột: đặt chuột bên phải bàn phím, lòng bàn tay úp nhẹ lên lưng chuột, ngón trỏ đặt nút trái, ngón giữa đặt nút phải, ngón cái và hai ngón còn lại giữ hai bên.\n- GV làm mẫu chậm từng thao tác trên máy chiếu: di chuyển chuột, nháy chuột trái một lần để chọn, nháy nút phải để hiện bảng chọn, nháy đúp hai lần liên tiếp thật nhanh để mở, nhấn giữ nút trái rồi kéo và nhả để kéo thả.\n- GV hỏi: muốn mở một biểu tượng trên màn hình nền thì dùng thao tác nào?","hs":"- HS quan sát rồi đặt tay lên chuột của nhóm mình, làm theo mẫu.\n- HS gọi đúng tên năm thao tác: di chuyển, nháy, nháy nút phải, nháy đúp, kéo thả.\n- HS trả lời: nháy đúp chuột trái vào biểu tượng thì mở được."},{"ten":"3. Thực hành","gv":"- (15 phút) GV giao lần lượt ba việc: di chuyển con trỏ chuột tới biểu tượng Recycle Bin; nháy một lần để biểu tượng đổi màu; nháy đúp để mở cửa sổ rồi nháy nút đóng ở góc trên bên phải.\n- Việc thứ tư: nhấn giữ nút trái ở biểu tượng, kéo sang góc khác của màn hình nền rồi mới nhả tay ra.\n- Lỗi HS hay mắc và cách xử lí: nháy đúp hai lần quá chậm nên không mở được, GV đếm nhịp một hai thật nhanh cho HS bấm theo; kéo thả nhả chuột sớm nên biểu tượng rơi giữa đường, GV nhắc giữ chặt nút trái cho tới khi tới đúng chỗ mới nhả; cầm chuột bằng cả bàn tay nắm chặt hoặc nhấc chuột lên khỏi bàn, GV chỉnh lại tư thế tay và nhắc rê nhẹ chuột trên mặt bàn.","hs":"- HS luân phiên thực hành từng việc, bạn chưa tới lượt quan sát và nhắc bạn bằng lời.\n- HS mở và đóng được cửa sổ, kéo thả được biểu tượng tới vị trí mới.\n- HS nhận ra lỗi của mình, bấm nhanh hơn hoặc giữ chặt nút trái rồi làm lại cho đúng."},{"ten":"4. Luyện tập — Vận dụng","gv":"- (8 phút) GV cho HS làm phiếu học tập nối cột: nối tên thao tác với việc làm tương ứng, ví dụ mở một biểu tượng nối với nháy đúp.\n- GV hỏi thêm: muốn di chuyển một biểu tượng sang chỗ khác thì dùng thao tác nào, muốn xem bảng chọn thì dùng nút nào?\n- GV giao nhiệm vụ vận dụng: về nhà em hãy nhờ người lớn mở máy tính hoặc máy tính bảng của gia đình rồi tự tay nháy đúp mở một biểu tượng em thích, sau đó kéo thả biểu tượng đó sang một chỗ khác trên màn hình nền và nhớ trả lại chỗ cũ.\n- GV gợi ý thêm tình huống thật: khi xem tivi thông minh hoặc dùng máy tính ở thư viện, em hãy để ý xem con trỏ chuột thay đổi hình dạng thế nào khi đưa qua các vùng khác nhau.\n- GV nhận xét giờ thực hành, hướng dẫn HS tắt máy đúng cách và dặn tiết sau học về bàn phím.","hs":"- HS làm phiếu nối cột, đổi phiếu kiểm tra chéo với bạn cùng máy.\n- HS trả lời: kéo thả chuột để di chuyển, nháy nút phải để hiện bảng chọn.\n- HS ghi nhớ nhiệm vụ vận dụng: về nhà xin phép người lớn để tập nháy đúp mở một biểu tượng và kéo thả biểu tượng sang chỗ khác rồi trả lại chỗ cũ.\n- HS nhận nhiệm vụ quan sát hình dạng con trỏ chuột khi dùng thiết bị ở nhà hoặc ở thư viện, tiết sau kể lại cho lớp nghe.\n- HS tắt máy đúng cách, kê lại ghế, xếp chuột và bàn phím ngay ngắn trước khi ra khỏi phòng máy."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV hướng dẫn HS đặt tay lên chuột và làm từng thao tác: di chuột, nháy, nháy đúp, kéo thả; HS luyện bằng phần mềm xếp hình — kéo mảnh ghép vào đúng chỗ thì mảnh dính lại, sai thì bật ra, HS biết ngay mình làm đúng hay chưa.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) HS dùng chuột vẽ một hình đơn giản trong phần mềm vẽ: kéo để tạo nét, nháy để chọn màu, kéo thả để di chuyển hình; đây là sản phẩm đầu tiên trên máy tính do chính tay HS điều khiển chuột làm ra.\n⚠ (Miền 4: An toàn) Cầm chuột nhẹ tay, không giật dây chuột, không đập chuột xuống bàn; chỉ nháy trong phần mềm GV đã mở sẵn, không nháy vào biểu tượng khác trên màn hình; nghỉ tay và duỗi các ngón sau mỗi 20 phút.","hs":"- HS làm được các thao tác chuột: di, nháy, nháy đúp, kéo thả.\n- HS vẽ và lưu được một hình đơn giản bằng chuột."}]},
{"lop":3,"mon":"Tin học","tuan":9,"tiet":9,"bai":"Bài 4: Làm việc với máy tính (Tiết 3)","yccd":"1. Năng lực Tin học (đặc thù):\n- Khởi động được máy tính, kích hoạt được một phần mềm ứng dụng, ra khỏi hệ thống đúng cách.\n- Nêu được ví dụ thao tác không đúng cách gây tổn hại thiết bị.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS thực hiện đủ một vòng thao tác từ bật máy tới tắt máy theo phiếu hướng dẫn.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: hằng ngày em bật/tắt ti vi thế nào? Với máy tính thì sao?","hs":"- HS chia sẻ; dự đoán cách bật/tắt máy tính."},{"ten":"2. Khám phá – Thực hành: Bật/tắt máy tính","gv":"- GV làm mẫu: bật máy, quan sát màn hình nền; nháy đúp mở phần mềm; tắt máy đúng cách (Start\\Power\\Shut down).","hs":"- HS quan sát rồi thực hành theo từng bước; báo cáo kết quả."},{"ten":"3. Thực hành: Mở và đóng phần mềm","gv":"- GV hướng dẫn HS nháy đúp mở một phần mềm, thao tác đơn giản, rồi đóng phần mềm.","hs":"- HS thực hành mở/đóng phần mềm; nêu thao tác sai có thể gây hỏng thiết bị."},{"ten":"4. Luyện tập – Vận dụng","gv":"- GV cho HS làm bài tập chọn thao tác tắt máy đúng; nhắc tắt máy đúng cách ở nhà.","hs":"- HS làm bài; về nhà luyện bật/tắt máy đúng cách (nếu có điều kiện)."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS làm trọn một vòng thao tác theo phiếu hướng dẫn có hình từng bước: bật máy, mở phần mềm, làm một việc nhỏ, lưu lại, đóng phần mềm, tắt máy; quên bước nào thì nhìn lại phiếu chứ không làm bừa.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS nhận ra các dấu hiệu máy báo cho người dùng: vòng tròn quay là máy đang bận, cửa sổ hỏi có lưu hay không, thanh báo pin yếu; HS đọc dấu hiệu để biết khi nào nên chờ, khi nào phải gọi thầy cô.\n⚠ (Miền 4: An toàn) Tắt máy bằng lệnh tắt trong máy chứ không rút điện và không bấm giữ nút nguồn khi chưa được phép; không đăng nhập bằng tài khoản của người khác; rời phòng máy phải kê lại ghế, không để nước gần máy.","hs":"- HS thực hiện đủ một vòng thao tác từ bật máy tới tắt máy theo phiếu hướng dẫn.\n- HS đọc được dấu hiệu máy báo và biết khi nào cần gọi thầy cô."}]},
{"lop":3,"mon":"Tin học","tuan":10,"tiet":10,"bai":"Bài 5: Sử dụng bàn phím (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Chỉ ra được khu vực chính của bàn phím và gọi được tên các hàng phím.\n- Biết vị trí hàng phím cơ sở và hai phím có gai F, J.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đặt tay đúng hàng phím cơ sở và tìm được phím cần gõ.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV chiếu hình bàn phím phóng to và đặt một bàn phím thật lên bàn GV cho HS quan sát.\n- GV hỏi: bàn phím có nhiều phím xếp thành mấy hàng, phím nào dài nhất, phím nào to nhất?\n- GV cho hai HS lên chỉ trên bàn phím thật rồi dẫn vào bài.","hs":"- HS quan sát hình và bàn phím thật, đếm số hàng phím.\n- HS nêu dự đoán: phím dài nhất ở dưới cùng, phím to có chữ Enter ở bên phải.\n- HS lên bảng chỉ và gọi tên phím mình biết."},{"ten":"2. Khám phá: Khu vực chính và các hàng phím","gv":"- (12 phút) GV chỉ trên hình phóng to khu vực chính của bàn phím và gọi tên lần lượt từ trên xuống: hàng phím số, hàng phím trên, hàng phím cơ sở, hàng phím dưới, hàng phím chứa phím cách.\n- GV nhấn mạnh hàng phím cơ sở là hàng có hai phím F và J, trên hai phím này có gờ nổi nhỏ gọi là gai.\n- GV hỏi: vì sao hai phím F và J lại có gai? Dự kiến HS trả lời: để đặt hai ngón trỏ mà không phải cúi nhìn xuống bàn phím.\n- GV chốt kiến thức, giới thiệu thêm phím Enter để xuống dòng, phím Backspace để xoá, phím Shift để gõ chữ hoa.","hs":"- HS chỉ và gọi tên đúng năm hàng phím trên hình và trên bàn phím thật.\n- HS sờ tìm hai phím có gai F và J, nêu công dụng của gai.\n- HS ghi nhớ hộp kiến thức và tên ba phím Enter, Backspace, Shift."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu học tập có hình bàn phím trắng, yêu cầu HS tô màu hàng phím cơ sở và khoanh tròn hai phím có gai.\n- GV tổ chức trò chơi Ai nhanh hơn: GV đọc tên một hàng phím hoặc một phím, HS chỉ nhanh trên hình của mình, tổ nào nhiều bạn chỉ đúng thì thắng.\n- GV nhận xét, sửa những chỗ HS còn nhầm giữa hàng phím trên và hàng phím dưới.","hs":"- HS tô màu và khoanh đúng trên phiếu học tập.\n- HS tham gia trò chơi, chỉ nhanh và đúng theo hiệu lệnh của GV.\n- HS tự sửa chỗ nhầm, nhắc lại thứ tự các hàng phím từ trên xuống dưới."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy tìm hai phím có gai trên bàn phím ở lớp hoặc ở nhà, đặt ngón trỏ trái vào phím F, ngón trỏ phải vào phím J rồi nhắm mắt thử tìm lại.\n- GV nhắc giữ gìn thiết bị: gõ nhẹ tay, không đập mạnh, không tự bẩy nút bàn phím ra, không để nước và đồ ăn gần bàn phím.\n- GV dặn tiết sau học cách đặt mười ngón tay lên bàn phím và luyện gõ.","hs":"- HS thực hành đặt hai ngón trỏ đúng vị trí xuất phát, thử tìm lại khi không nhìn.\n- HS nhắc lại các việc cần làm để giữ gìn bàn phím.\n- HS ghi nhớ nhiệm vụ chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hình bàn phím phóng to, chỉ rõ các khu vực: hàng phím cơ sở, phím cách, phím Enter, phím xoá; HS tìm đúng hai phím F và J có gờ nổi trên bàn phím thật để đặt hai ngón trỏ mà không phải cúi nhìn xuống.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS gõ thử tên riêng của mình và vài từ ngắn, tự đếm số lần gõ nhầm rồi gõ lại; HS nhận ra đặt tay đúng hàng phím cơ sở thì tìm phím nhanh hơn hẳn so với dò từng phím bằng một ngón.\n⚠ (Miền 4: An toàn) Gõ nhẹ tay, không đập mạnh và không tì cả cánh tay lên bàn phím; không tự bẩy nút bàn phím ra; nghỉ tay sau mỗi 20 phút; không gõ họ tên đầy đủ, địa chỉ nhà của mình vào bất kì ô nào trên máy.","hs":"- HS đặt tay đúng hàng phím cơ sở và tìm được phím cần gõ.\n- HS gõ được tên mình và vài từ ngắn, tự đếm và sửa lỗi."}]},
{"lop":3,"mon":"Tin học","tuan":11,"tiet":11,"bai":"Bài 5: Sử dụng bàn phím (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết đặt các ngón tay đúng vị trí trên hàng phím cơ sở.\n- Thực hiện được thao tác gõ phím ở hàng cơ sở, hàng trên, hàng dưới đúng quy định.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS đọc được số từ và số lỗi phần mềm báo, đặt mục tiêu cho lượt luyện sau.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV chia nhóm 2 đến 3 HS một máy, quy định mỗi bạn luyện gõ 4 phút rồi đổi lượt để bạn nào cũng được thực hành.\n- GV yêu cầu cả lớp đặt hai ngón trỏ lên hai phím có gai F và J, các ngón còn lại đặt sang hai bên trên cùng hàng.\n- GV kiểm tra nhanh từng máy, nhắc HS ngồi thẳng lưng, cổ tay thẳng, không tì cánh tay lên mép bàn.","hs":"- HS về đúng máy theo nhóm, nhớ lượt thực hành của mình.\n- HS đặt tay đúng vị trí xuất phát trên hàng phím cơ sở.\n- HS tự chỉnh lại ghế và tư thế tay theo nhắc nhở của GV."},{"ten":"2. Khám phá: Vị trí đặt ngón tay","gv":"- (8 phút) GV chiếu hình bàn tay đặt trên bàn phím, hướng dẫn quy tắc: tay trái đặt các ngón lên A, S, D, F; tay phải đặt lên J, K, L và phím dấu chấm phẩy; hai ngón cái đặt hờ trên phím cách.\n- GV hướng dẫn cách vươn ngón: gõ phím hàng trên thì vươn ngón lên rồi đưa ngón về ngay hàng cơ sở; gõ phím hàng dưới thì hạ ngón xuống rồi cũng đưa về hàng cơ sở.\n- GV làm mẫu gõ chậm dãy asdf và jkl trên máy chiếu, vừa gõ vừa nói tên ngón đang dùng.","hs":"- HS đặt tám ngón tay đúng vị trí trên hàng phím cơ sở, hai ngón cái đặt hờ trên phím cách.\n- HS quan sát mẫu, gõ theo GV dãy asdf và jkl, sau mỗi lần gõ đưa ngón về đúng chỗ cũ.\n- HS nêu được quy tắc gõ xong phải đưa ngón về hàng phím cơ sở."},{"ten":"3. Thực hành gõ phím","gv":"- (15 phút) GV hướng dẫn HS mở phần mềm luyện gõ bằng cách nháy đúp vào biểu tượng phần mềm trên màn hình nền, nếu không có thì mở phần mềm soạn thảo đơn giản.\n- GV giao ba lượt gõ: lượt một gõ hàng cơ sở, lượt hai gõ thêm hàng trên, lượt ba gõ thêm hàng dưới; gõ sai thì bấm phím Backspace để xoá rồi gõ lại.\n- Lỗi HS hay mắc và cách xử lí: gõ một ngón và cúi nhìn bàn phím, GV che tay HS bằng một tờ bìa và cho gõ chậm lại theo đúng ngón; bật nhầm phím Caps Lock nên ra toàn chữ hoa, GV chỉ đèn báo Caps Lock và hướng dẫn bấm lại phím đó một lần; nhấn giữ phím quá lâu nên ra một dãy chữ giống nhau, GV nhắc gõ nhẹ rồi nhấc ngón lên ngay.","hs":"- HS nháy đúp mở đúng phần mềm, đặt tay vào vị trí xuất phát rồi bắt đầu gõ.\n- HS gõ đủ ba lượt theo yêu cầu, dùng phím Backspace xoá chỗ gõ sai.\n- HS giữ đúng tư thế: lưng thẳng, cổ tay thẳng, mắt nhìn màn hình chứ không cúi nhìn xuống bàn phím.\n- HS nhận ra lỗi của mình, tắt Caps Lock, gõ nhẹ tay và gõ lại đúng ngón."},{"ten":"4. Luyện tập - Vận dụng","gv":"- (8 phút) GV cho HS gõ tên lớp và một câu ngắn GV đọc, dùng phím Shift để gõ chữ hoa đầu câu, phím cách để tách chữ và phím Enter để xuống dòng.\n- GV cho vài HS đọc lại câu mình vừa gõ trên màn hình và tự chỉ ra chỗ còn thiếu dấu cách hay thừa chữ.\n- GV nhận xét giờ học, dặn HS luyện gõ mười ngón ở nhà nếu có máy; hướng dẫn HS tắt phần mềm, tắt máy đúng cách rồi mới rời phòng máy.","hs":"- HS gõ được tên lớp và câu ngắn, biết dùng phím Shift, phím cách và phím Enter.\n- HS đọc lại bài trên màn hình, tự sửa chỗ sai bằng phím Backspace.\n- HS tắt phần mềm và tắt máy đúng cách, xếp lại ghế trước khi ra về."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS luyện gõ bằng phần mềm có chấm điểm: sau mỗi lượt máy báo số từ gõ được và số lỗi; HS ghi kết quả vào phiếu và tự đặt mục tiêu cho lượt sau — nhờ máy chấm, HS nhìn thấy mình tiến bộ từng lượt chứ không đoán mò.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) HS gõ lại một câu ngắn GV cho, đọc lại trên màn hình rồi tự sửa chỗ thiếu dấu, thiếu chữ hoa đầu câu, thừa dấu cách; đây là đoạn văn bản đầu tiên do chính HS gõ ra trên máy.\n⚠ (Miền 4: An toàn) Chỉ mở phần mềm luyện gõ thầy cô chỉ định, không mở trò chơi hay trang khác trong giờ thực hành; ngồi đúng tư thế, cổ tay thẳng; kết quả của mình cao hay thấp cũng không chê bai kết quả của bạn.","hs":"- HS đọc được số từ và số lỗi phần mềm báo, đặt mục tiêu cho lượt luyện sau.\n- HS gõ và sửa được một câu ngắn đúng quy tắc viết hoa, dấu câu."}]},
{"lop":3,"mon":"Tin học","tuan":12,"tiet":12,"bai":"Bài 6: Khám phá thông tin trên Internet (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được ví dụ về tin tức, chương trình giải trí có thể xem khi truy cập Internet.\n- Nêu được ví dụ thông tin không có sẵn trong máy nhưng tìm được trên Internet.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS gọi tên được các thành phần của một trang web và hiểu liên kết dùng để chuyển trang.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV hỏi: ở nhà em đã từng xem gì trên Internet, xem bằng máy tính, ti vi hay điện thoại?\n- GV ghi nhanh câu trả lời lên bảng thành hai nhóm: xem để học và xem để giải trí.\n- GV dẫn vào bài: Internet là kho thông tin rất lớn, hôm nay lớp mình cùng tìm hiểu.","hs":"- HS chia sẻ trải nghiệm: xem phim hoạt hình, nghe bài hát, xem bản tin thời tiết, xem bài giảng.\n- HS xếp câu trả lời của mình vào đúng nhóm học tập hay giải trí.\n- HS lắng nghe và nêu điều mình muốn biết thêm về Internet."},{"ten":"2. Khám phá: Thông tin trên Internet","gv":"- (12 phút) GV giới thiệu Internet là mạng máy tính rất lớn nối các máy tính khắp nơi, nhờ đó em xem được tin tức và chương trình giải trí.\n- GV nêu câu hỏi: máy tính của lớp mình có sẵn bản tin thời tiết ngày mai không, muốn biết thì phải làm gì?\n- Dự kiến HS trả lời: máy không có sẵn, phải nối Internet để xem trên trang dự báo thời tiết.\n- GV chốt: có những thông tin không có sẵn trong máy tính nhưng tìm được trên Internet, ví dụ tin tức hôm nay, lịch chiếu phim, bài hát mới.","hs":"- HS lắng nghe, quan sát hình minh hoạ trong SGK về Internet.\n- HS trả lời câu hỏi và nêu thêm ví dụ thông tin không có sẵn trong máy.\n- HS đọc và ghi nhớ hộp kiến thức trong SGK."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu học tập, cho HS làm việc nhóm 4: kể ba thông tin học tập và ba chương trình giải trí có thể xem trên Internet.\n- GV tổ chức trò chơi chọn đúng sai: GV đọc từng câu, ví dụ mọi thứ trên Internet đều đúng, HS giơ thẻ Đ hoặc S.\n- GV chốt: Internet có rất nhiều thông tin nhưng không phải thông tin nào cũng đúng và cũng hợp với lứa tuổi các em.","hs":"- HS làm việc nhóm, ghi phiếu rồi cử đại diện trình bày trước lớp.\n- HS giơ thẻ Đ hoặc S và giải thích ngắn gọn vì sao chọn như vậy.\n- HS nhận xét bài của nhóm bạn, bổ sung ví dụ còn thiếu."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: về nhà em hãy nhờ bố mẹ mở giúp một trang dành cho thiếu nhi và kể lại tiết sau em đã xem được gì.\n- GV nhắc an toàn: chỉ vào mạng khi có người lớn bên cạnh, không nháy vào quảng cáo hay cửa sổ tự bật lên, không nhập họ tên và địa chỉ nhà vào bất kì ô nào.\n- GV dặn tiết sau học cách dùng Internet an toàn và chọn lọc thông tin phù hợp.","hs":"- HS ghi nhớ nhiệm vụ về nhà và cách nhờ người lớn hỗ trợ.\n- HS nhắc lại ba việc không được làm khi vào Internet.\n- HS ghi việc cần chuẩn bị cho tiết học sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở một trang dành cho thiếu nhi đã chọn sẵn, chỉ cho HS ô địa chỉ, tiêu đề trang, khối chữ, hình ảnh và các liên kết; GV nháy vào một liên kết để HS thấy mình vừa chuyển sang trang khác. GV thao tác máy, HS quan sát và đọc theo.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu song song hai trang: một trang của trường học, báo thiếu nhi hoặc cơ quan nhà nước và một trang không rõ của ai; HS chỉ ra trang nào ghi rõ tên đơn vị, địa chỉ liên hệ và nói vì sao thông tin ở đó đáng tin hơn.\n⚠ (Miền 4: An toàn) Chỉ xem những trang thầy cô đã mở sẵn; không nháy vào quảng cáo, cửa sổ tự bật lên hay nút tải về; không nhập họ tên, địa chỉ, số điện thoại vào bất kì ô nào; gặp hình ảnh hay lời lẽ đáng sợ thì úp màn hình xuống và gọi thầy cô ngay.","hs":"- HS gọi tên được các thành phần của một trang web và hiểu liên kết dùng để chuyển trang.\n- HS phân biệt được trang chính thống với trang không rõ nguồn gốc."}]},
{"lop":3,"mon":"Tin học","tuan":13,"tiet":13,"bai":"Bài 6: Khám phá thông tin trên Internet (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết được không phải thông tin nào trên Internet cũng phù hợp với lứa tuổi.\n- Có ý thức truy cập Internet an toàn, chọn lọc thông tin phù hợp.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được cách đọc mô tả kết quả để chọn trang nên mở.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV nêu tình huống: đang xem phim hoạt hình thì hiện ra một hình ảnh đáng sợ và một dòng chữ mời bấm vào để nhận quà, em sẽ làm gì?\n- GV cho HS thảo luận cặp đôi trong 2 phút rồi mời vài cặp trả lời.\n- GV ghi nhận các cách xử lí lên bảng và dẫn vào bài.","hs":"- HS thảo luận cặp đôi, nêu cách xử lí ban đầu.\n- HS trả lời: tắt đi, không bấm vào, gọi bố mẹ hoặc thầy cô.\n- HS lắng nghe, so sánh cách xử lí của mình với của bạn."},{"ten":"2. Khám phá: An toàn khi truy cập Internet","gv":"- (12 phút) GV hướng dẫn ba việc nên làm: chỉ xem nội dung phù hợp lứa tuổi, chỉ vào mạng khi có người lớn bên cạnh, không tin ngay mọi điều đọc được.\n- GV nêu câu hỏi: vì sao có những nội dung trên Internet không dành cho các em? Dự kiến HS trả lời: vì nội dung đó đáng sợ, không đúng, làm em học theo điều xấu.\n- GV giới thiệu cách xử lí khi gặp nội dung không phù hợp: úp màn hình xuống hoặc tắt cửa sổ và báo ngay cho người lớn.\n- GV chốt kiến thức và cho HS đọc lại hộp ghi nhớ trong SGK.","hs":"- HS lắng nghe, nêu việc nên làm và không nên làm khi lên Internet.\n- HS trả lời câu hỏi và lấy ví dụ nội dung không phù hợp với lứa tuổi.\n- HS ghi nhớ cách xử lí: rời khỏi trang đó và báo cho người lớn biết."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV chia nhóm 4, phát ba tình huống để HS đóng vai xử lí: gặp quảng cáo lạ hiện lên giữa màn hình; gặp đoạn phim không phù hợp; người lạ nhắn tin hỏi tên trường của em.\n- GV yêu cầu mỗi nhóm nói rõ em làm gì trước, làm gì sau và báo cho ai.\n- GV nhận xét, chốt cách xử lí an toàn: không bấm, không trả lời, rời khỏi và báo ngay người lớn.","hs":"- HS làm việc nhóm, phân vai và diễn lại cách xử lí tình huống.\n- HS chọn cách xử lí an toàn và giải thích lí do lựa chọn.\n- HS nhận xét nhóm bạn, bổ sung cách xử lí hay hơn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV hỏi: khi cần tìm thông tin cho bài học, em nhờ ai giúp và nên chọn trang nào?\n- GV gợi ý: nhờ thầy cô, bố mẹ, anh chị; chọn trang của nhà trường, báo thiếu nhi hoặc cơ quan nhà nước vì có ghi rõ tên đơn vị.\n- GV dặn dò: mỗi lần ngồi máy không quá 30 phút, nghỉ mắt sau 20 phút; chuẩn bị tiết sau học bài sắp xếp để dễ tìm.","hs":"- HS chia sẻ cách làm của mình, nêu ý thức nhờ người lớn hướng dẫn.\n- HS kể tên vài trang đáng tin mà em hoặc gia đình vẫn xem.\n- HS ghi nhớ quy tắc thời gian dùng máy và việc chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV nhập từ khoá mẫu cho một câu hỏi của bài học, đọc to phần mô tả của vài kết quả rồi cùng HS chọn kết quả nên mở; HS học cách đọc lướt để chọn chứ không mở bừa kết quả đầu tiên.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV chỉ cho HS thấy đoạn trả lời tóm tắt do máy tự viết ở đầu trang kết quả và nói rõ đó là do máy đọc nhiều trang rồi viết lại nên có thể thiếu hoặc sai; GV mở trang gốc để cả lớp cùng đối chiếu. HS quan sát, chưa tự tìm kiếm một mình.\n⚠ (Miền 4: An toàn) Chỉ tìm những gì phục vụ bài học và chỉ tìm khi có thầy cô bên cạnh; không tải tệp lạ về máy; không cho ai trên mạng biết tên trường, tên lớp, giờ tan học của mình; ai hỏi chuyện riêng thì kể lại ngay với cha mẹ, thầy cô.","hs":"- HS nêu được cách đọc mô tả kết quả để chọn trang nên mở.\n- HS nêu được vì sao phần tóm tắt do máy viết vẫn phải mở trang gốc kiểm tra lại."}]},
{"lop":3,"mon":"Tin học","tuan":14,"tiet":14,"bai":"Bài 7: Sắp xếp để dễ tìm (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Giải thích được: sắp xếp hợp lí thì khi cần sẽ tìm được nhanh hơn.\n- Sắp xếp được đồ vật hay dữ liệu hợp lí theo một số yêu cầu cụ thể.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.3 CB1a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS nêu được lợi ích của việc sắp xếp có quy tắc.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV chiếu hai bức ảnh: một giá sách để lộn xộn và một giá sách xếp gọn theo môn học.\n- GV nêu tình huống thi tìm nhanh quyển sách Toán và hỏi: ở giá nào em tìm nhanh hơn, vì sao?\n- GV dẫn vào bài: sắp xếp hợp lí thì khi cần sẽ tìm được nhanh hơn.","hs":"- HS quan sát hai bức ảnh, so sánh và trả lời.\n- HS nêu: giá sách xếp gọn tìm nhanh hơn vì sách cùng loại để cùng một chỗ.\n- HS kể thêm những chỗ ở nhà em thường bị lộn xộn nên khó tìm."},{"ten":"2. Khám phá: Vì sao cần sắp xếp","gv":"- (12 phút) GV chia nhóm 4, phát cho mỗi nhóm một rổ đồ dùng học tập để lẫn lộn và yêu cầu nhóm tự nghĩ cách xếp lại cho dễ tìm.\n- GV nêu câu hỏi gợi mở: nhóm em xếp theo dấu hiệu nào, theo loại đồ dùng, theo màu sắc hay theo kích thước?\n- Dự kiến HS trả lời: bút để một chỗ, thước để một chỗ, tẩy để một chỗ; hoặc xếp theo màu cho dễ nhìn.\n- GV chốt: có thể sắp xếp theo nhóm hoặc theo thứ tự; sắp xếp có quy tắc thì ai cũng tìm được nhanh, không chỉ riêng mình.","hs":"- HS làm việc nhóm, bàn cách xếp rồi sắp lại rổ đồ dùng của nhóm.\n- HS nêu rõ nhóm mình xếp theo dấu hiệu nào và vì sao chọn cách đó.\n- HS đọc và ghi nhớ hộp kiến thức trong SGK."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV cho HS làm bài trong SGK: sắp xếp một nhóm đồ vật theo yêu cầu, ví dụ xếp tên bạn theo bảng chữ cái, xếp số theo thứ tự từ bé đến lớn.\n- GV tổ chức trò chơi Ai nhanh hơn giữa hai tổ: một tổ tìm trong rổ đã xếp, một tổ tìm trong rổ để lộn xộn, cùng tìm một món đồ.\n- GV chốt lại kết quả cuộc thi để HS tự rút ra lợi ích của việc sắp xếp.","hs":"- HS làm bài và trình bày cách sắp xếp của mình trước lớp.\n- HS tham gia trò chơi, đo xem tổ nào tìm nhanh hơn.\n- HS rút ra kết luận: rổ đã sắp xếp thì tìm nhanh hơn hẳn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: về nhà em hãy xếp lại ngăn bàn hoặc cặp sách của mình theo một quy tắc và nói cho người thân biết quy tắc đó.\n- GV liên hệ: máy tính cũng phải sắp xếp dữ liệu theo quy tắc thì mới tìm lại được nhanh.\n- GV dặn tiết sau học cách tìm nhanh dựa trên sự sắp xếp; nhắc HS giữ gìn đồ dùng của lớp, dùng xong xếp lại đúng chỗ.","hs":"- HS nhận nhiệm vụ, nêu quy tắc mình định dùng để xếp cặp sách.\n- HS liên hệ được việc sắp xếp đồ vật với việc sắp xếp dữ liệu trong máy tính.\n- HS xếp lại rổ đồ dùng của nhóm về đúng chỗ trước khi hết giờ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV đổ lẫn một rổ đồ dùng học tập rồi cho hai tổ thi tìm một món: tổ để lộn xộn và tổ đã xếp theo nhóm. HS tự rút ra rằng sắp xếp có quy tắc thì tìm nhanh hơn nhiều — đây chính là lí do máy tính phải sắp dữ liệu.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu một danh sách trên máy rồi bấm nút sắp xếp theo tên, theo ngày để HS thấy cùng một danh sách được xếp lại tức thì theo nhiều cách; HS nói mỗi cách xếp giúp tìm nhanh việc gì.\n⚠ (Miền 4: An toàn) Giữ gìn đồ dùng của lớp khi chơi trò tìm nhanh, tìm xong xếp lại đúng chỗ; nhường bạn và không tranh giành; quan sát GV thao tác trên máy, chưa tự bấm vào máy của GV.","hs":"- HS nêu được lợi ích của việc sắp xếp có quy tắc.\n- HS đọc được một danh sách đã sắp xếp theo tên hoặc theo ngày."}]},
{"lop":3,"mon":"Tin học","tuan":15,"tiet":15,"bai":"Bài 7: Sắp xếp để dễ tìm (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được cách tìm đúng và nhanh đối tượng cần tìm dựa trên sự sắp xếp.\n- Vận dụng sắp xếp và tìm kiếm trong tình huống thực tế.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.3 CB1a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS nêu được vì sao máy tính tìm nhanh khi dữ liệu đã sắp xếp.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV tổ chức thi tìm nhanh giữa hai tổ: tổ một tìm quyển sách trong giá đã xếp theo bảng chữ cái, tổ hai tìm trong giá chưa xếp.\n- GV bấm giờ và ghi kết quả của hai tổ lên bảng.\n- GV hỏi: vì sao tổ một tìm nhanh hơn dù cả hai tổ cùng tìm một quyển sách?","hs":"- HS hai tổ tham gia thi tìm nhanh, cả lớp cổ vũ và theo dõi thời gian.\n- HS so sánh kết quả và nhận ra giá đã sắp xếp thì tìm nhanh hơn.\n- HS trả lời: vì biết trước sách xếp theo thứ tự nên tìm thẳng tới chỗ cần tìm."},{"ten":"2. Khám phá: Tìm kiếm dựa trên sắp xếp","gv":"- (12 phút) GV hướng dẫn cách tìm dựa trên trật tự đã có: tìm tên bạn trong danh sách xếp theo bảng chữ cái thì xem chữ cái đầu để mở đúng phần; tìm số trong dãy xếp tăng dần thì bỏ qua các số quá bé.\n- GV nêu câu hỏi: muốn tìm bạn tên Nam trong danh sách lớp xếp theo bảng chữ cái, em mở từ đầu danh sách hay tìm tới nhóm chữ N?\n- Dự kiến HS trả lời: tìm tới nhóm chữ N cho nhanh, không cần đọc từ đầu.\n- GV chốt: nhờ biết quy tắc sắp xếp, em bỏ qua được rất nhiều chỗ không cần xem.","hs":"- HS quan sát ví dụ, nêu cách tìm nhanh với danh sách xếp theo bảng chữ cái.\n- HS trả lời câu hỏi và làm thử với danh sách lớp mình.\n- HS ghi nhớ hộp kiến thức về tìm kiếm dựa trên sắp xếp."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu học tập có một danh sách đã sắp xếp, yêu cầu HS tìm ba đối tượng theo yêu cầu và ghi lại em đã tìm theo cách nào.\n- GV hỏi thêm: nếu danh sách chưa sắp xếp thì em phải làm gì, mất nhiều thời gian hơn không?\n- GV nhận xét, tuyên dương HS giải thích được cách tìm chứ không chỉ nêu đáp án.","hs":"- HS làm phiếu, tìm đúng ba đối tượng theo yêu cầu.\n- HS giải thích cách tìm của mình trước lớp.\n- HS trả lời: nếu chưa sắp xếp thì phải dò từng dòng nên mất nhiều thời gian hơn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy sắp xếp lại góc học tập hoặc tủ sách của em ở nhà theo một quy tắc để dễ tìm.\n- GV gợi ý đặt tên cho từng nhóm, ví dụ ngăn Sách Toán, hộp Bút màu, để lần sau tìm không phải mở hết ra.\n- GV dặn tiết sau học về sơ đồ hình cây; nhắc HS chỉ tìm trong đồ dùng của mình, không tự ý mở cặp của bạn.","hs":"- HS nhận nhiệm vụ, nêu quy tắc sẽ dùng để xếp tủ sách của mình.\n- HS nêu được lợi ích của việc đặt tên dễ hiểu cho từng nhóm.\n- HS ghi việc chuẩn bị cho tiết sau và nhắc lại quy tắc tôn trọng đồ dùng của bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS tự nghĩ một quy tắc để xếp bài làm và đồ dùng của mình, đặt tên cho từng nhóm rồi thi tìm nhanh với bạn; HS giải thích được vì sao đặt tên dễ hiểu thì tìm lại nhanh hơn đặt tên qua loa.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV gõ một từ khoá vào ô tìm kiếm của máy tính cho HS thấy máy lọc ra ngay những mục có chứa từ đó; GV giải thích máy tìm nhanh được là nhờ dữ liệu đã được sắp xếp và đặt tên sẵn.\n⚠ (Miền 4: An toàn) Đặt tên nhóm, tên bài làm bằng nội dung chứ không đặt tên có họ tên đầy đủ, địa chỉ nhà; chỉ tìm trong thư mục của mình, không mở thư mục của bạn; không xoá bất cứ mục nào khi chưa được thầy cô cho phép.","hs":"- HS đặt được tên dễ hiểu cho các nhóm đồ vật, bài làm của mình.\n- HS nêu được vì sao máy tính tìm nhanh khi dữ liệu đã sắp xếp."}]},
{"lop":3,"mon":"Tin học","tuan":16,"tiet":16,"bai":"Bài 8: Sơ đồ hình cây. Tổ chức thông tin trong máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết có thể biểu diễn một cách sắp xếp, phân loại bằng sơ đồ hình cây.\n- Đọc và vẽ được sơ đồ hình cây đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc được sơ đồ hình cây và chỉ đúng vị trí của mình trên sơ đồ.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV chiếu sơ đồ cây gia đình gồm ông bà, bố mẹ, các con và hỏi: các ô được nối với nhau bằng gì, ô nào ở trên cùng?\n- GV chiếu tiếp sơ đồ phân loại con vật thành nhóm vật nuôi và nhóm thú rừng.\n- GV dẫn vào bài: cách vẽ phân nhánh như thế gọi là sơ đồ hình cây.","hs":"- HS quan sát, nêu: các ô nối với nhau bằng các đoạn thẳng, ô ông bà ở trên cùng.\n- HS chỉ ra nhánh nào thuộc nhóm vật nuôi, nhánh nào thuộc nhóm thú rừng.\n- HS nhận ra cách biểu diễn phân nhánh từ trên xuống dưới."},{"ten":"2. Khám phá: Sơ đồ hình cây","gv":"- (12 phút) GV giới thiệu các thành phần của sơ đồ hình cây: ô trên cùng là gốc, từ gốc toả ra các nhánh, mỗi nhánh lại có thể chia tiếp thành nhánh nhỏ hơn.\n- GV nêu câu hỏi: trong sơ đồ trường học, ô Lớp 3A nằm trong ô nào, ô đó lại nằm trong ô nào nữa?\n- Dự kiến HS trả lời: Lớp 3A nằm trong Khối 3, Khối 3 nằm trong Trường.\n- GV chốt: sơ đồ hình cây dùng để biểu diễn cách sắp xếp, phân loại; nhánh con luôn nằm trong nhánh cha.","hs":"- HS quan sát và gọi tên các thành phần: gốc, nhánh, nhánh con.\n- HS trả lời câu hỏi, chỉ đúng đường đi từ gốc tới ô Lớp 3A.\n- HS đọc và ghi nhớ hộp kiến thức về sơ đồ hình cây."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu học tập, cho HS làm việc nhóm 4 vẽ một sơ đồ hình cây đơn giản phân loại đồ dùng học tập thành nhóm để viết và nhóm để đo, vẽ.\n- GV gợi ý: viết tên nhóm lớn trước rồi mới kẻ nhánh xuống các món đồ cụ thể.\n- GV nhận xét bài của vài nhóm, chỉ ra chỗ đặt nhầm nhánh con sang nhánh khác.","hs":"- HS làm việc nhóm, vẽ sơ đồ hình cây vào phiếu học tập.\n- HS treo bài lên bảng nhóm và trình bày sơ đồ của nhóm mình.\n- HS nhận xét bài của nhóm bạn, sửa lại chỗ đặt nhầm nhánh."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy vẽ sơ đồ hình cây gia đình em hoặc sơ đồ phân loại truyện và sách giáo khoa trên giá sách của em.\n- GV liên hệ: máy tính cũng sắp xếp các tệp và thư mục theo dạng hình cây như vậy.\n- GV dặn tiết sau tìm hiểu tệp, thư mục và ổ đĩa trong máy tính.","hs":"- HS nhận nhiệm vụ, phác nhanh ý tưởng sơ đồ của mình ra nháp.\n- HS liên hệ được sơ đồ hình cây với cách máy tính sắp xếp dữ liệu.\n- HS ghi việc chuẩn bị cho tiết học sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu sơ đồ hình cây của nhà trường: trường → khối → lớp → tổ, mở dần từng nhánh cho HS thấy nhánh con luôn nằm trong nhánh cha; HS chỉ đúng vị trí của tổ mình trên sơ đồ.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS sắp một danh sách cho sẵn thành sơ đồ hình cây trên bảng kéo thả của máy chiếu: mục lớn ở trên, mục nhỏ ở dưới; đặt sai chỗ thì kéo lại, làm tới khi cả lớp thấy hợp lí.\n⚠ (Miền 4: An toàn) Chỉ kéo thả trong bài tập GV đã mở sẵn, không đổi cài đặt của máy; góp ý cho bạn khi bạn đặt sai chỗ bằng lời tử tế; không tranh nhau lên bảng.","hs":"- HS đọc được sơ đồ hình cây và chỉ đúng vị trí của mình trên sơ đồ.\n- HS sắp được một danh sách thành sơ đồ hình cây hợp lí."}]},
{"lop":3,"mon":"Tin học","tuan":17,"tiet":17,"bai":"Bài 8: Sơ đồ hình cây. Tổ chức thông tin trong máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được tệp, thư mục và ổ đĩa trong máy tính.\n- Mô tả được sơ lược vai trò của cấu trúc cây thư mục trong việc lưu trữ tệp và thư mục.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.3 CB1a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS nhận ra cây thư mục trong máy tính được tổ chức như sơ đồ hình cây.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV hỏi: ảnh chụp, bài hát, bài học của em được máy tính cất ở đâu và sắp xếp thế nào?\n- GV cho HS nhớ lại sơ đồ hình cây đã học ở tiết trước và dự đoán.\n- GV dẫn vào bài: máy tính cất mọi thứ trong các tệp, các tệp lại được xếp vào thư mục.","hs":"- HS dự đoán: máy tính cất trong ổ đĩa, trong các thư mục.\n- HS nhắc lại các thành phần của sơ đồ hình cây đã học.\n- HS nêu điều mình muốn biết thêm về cách máy tính lưu trữ."},{"ten":"2. Khám phá: Tệp, thư mục, ổ đĩa","gv":"- (12 phút) GV chiếu màn hình máy tính, giới thiệu tệp là nơi chứa một nội dung như bài văn, bức ảnh, bài hát; mỗi tệp có tên và có biểu tượng riêng.\n- GV giới thiệu thư mục là nơi chứa các tệp và các thư mục con; ổ đĩa là nơi chứa tất cả, thường có tên là ổ C hoặc ổ D.\n- GV nêu câu hỏi: nếu để tất cả các tệp lẫn vào một chỗ thì khi cần em tìm có dễ không, vì sao?\n- GV chốt: cây thư mục giúp lưu trữ có tổ chức, nhờ đó tìm lại nhanh; cho HS đọc hộp kiến thức.","hs":"- HS quan sát màn hình, phân biệt biểu tượng tệp và biểu tượng thư mục.\n- HS trả lời: để lẫn thì rất khó tìm vì phải xem hết từng tệp một.\n- HS nêu lại ba khái niệm tệp, thư mục, ổ đĩa và ghi nhớ hộp kiến thức."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu có hình một cây thư mục, yêu cầu HS xác định thư mục nào chứa tệp cần tìm và ghi lại đường đi từ ổ đĩa tới tệp đó.\n- GV hỏi thêm: muốn tìm tệp ảnh sinh nhật thì em mở thư mục nào trước, thư mục nào sau?\n- GV nhận xét, sửa cho HS còn nhầm giữa thư mục mẹ và thư mục con.","hs":"- HS đọc cây thư mục trên phiếu và chỉ đúng vị trí của tệp cần tìm.\n- HS ghi được đường đi từ ổ đĩa qua các thư mục tới tệp.\n- HS tự sửa chỗ nhầm giữa thư mục mẹ và thư mục con."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy vẽ cây thư mục để sắp xếp ảnh, bài học và bài vẽ của em cho dễ tìm; đặt tên từng thư mục thật dễ hiểu.\n- GV lưu ý đặt tên theo nội dung, không đặt tên có họ tên đầy đủ hay địa chỉ nhà.\n- GV dặn tiết sau vào phòng máy thực hành mở cửa sổ tệp và thư mục trên máy thật.","hs":"- HS vẽ cây thư mục của mình, đặt tên cho từng thư mục.\n- HS nêu tên thư mục mình chọn và giải thích vì sao tên đó dễ hiểu.\n- HS ghi nhớ nội quy phòng máy để chuẩn bị cho tiết thực hành."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở cửa sổ quản lí tệp trên máy thật, mở dần các thư mục để HS thấy cây thư mục của máy tính đúng như sơ đồ hình cây vừa học: thư mục mẹ chứa thư mục con, thư mục con chứa các tệp.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS nhìn đường dẫn hiện trên thanh địa chỉ và đọc thành lời đường đi từ ổ đĩa tới tệp; HS nói được muốn tìm một tệp thì phải đi theo nhánh nào chứ không mở lung tung từng thư mục.\n⚠ (Miền 4: An toàn) Chỉ mở xem, chưa xoá và chưa di chuyển bất cứ thư mục nào của máy; không mở thư mục của bạn khác; thấy cửa sổ lạ hiện ra thì để nguyên và gọi thầy cô, không tự bấm chọn.","hs":"- HS nhận ra cây thư mục trong máy tính được tổ chức như sơ đồ hình cây.\n- HS đọc được đường dẫn tới một tệp và biết đi theo nhánh để tìm."}]},
{"lop":3,"mon":"Tin học","tuan":18,"tiet":18,"bai":"Ôn tập giữa học kì I","yccd":"1. Năng lực Tin học (đặc thù):\n- Hệ thống hoá kiến thức các chủ đề đã học: thông tin và quyết định, xử lí thông tin, máy tính và em, bàn phím, Internet, sắp xếp – tổ chức thông tin.\n- Vận dụng làm bài kiểm tra, tự đánh giá kết quả học tập.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm bài ôn tương tác và tự nhận ra phần kiến thức mình còn chưa chắc.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV tổ chức trò chơi Truyền điện ôn nhanh: GV hỏi một câu ngắn, HS trả lời rồi chỉ bạn khác trả lời câu tiếp theo.\n- Các câu hỏi gợi ý: bộ phận nào của con người xử lí thông tin, hai phím có gai trên bàn phím là phím nào, muốn mở một biểu tượng thì dùng thao tác chuột nào?\n- GV ghi nhận những câu cả lớp còn lúng túng để tập trung ôn kĩ hơn.","hs":"- HS tham gia trò chơi, trả lời nhanh và chỉ bạn tiếp theo.\n- HS trả lời: bộ não xử lí thông tin, hai phím có gai là F và J, mở biểu tượng thì nháy đúp.\n- HS tự nhận ra phần kiến thức mình còn chưa nhớ chắc."},{"ten":"2. Ôn tập kiến thức","gv":"- (12 phút) GV hệ thống kiến thức bằng sơ đồ tư duy trên bảng theo bốn nhánh: thông tin và quyết định, xử lí thông tin, máy tính và em, bàn phím và chuột.\n- GV cho HS bổ sung từng nhánh bằng ví dụ của chính mình, GV ghi lên bảng.\n- GV nhấn mạnh các nội dung trọng tâm: ba bước thu nhận, xử lí, kết quả; tư thế ngồi đúng; năm thao tác chuột; tên các hàng phím.","hs":"- HS nhắc lại các đơn vị kiến thức theo từng nhánh của sơ đồ.\n- HS nêu ví dụ minh hoạ cho mỗi nhánh, bổ sung ý cho bạn.\n- HS chép lại sơ đồ tư duy vào vở để ôn ở nhà."},{"ten":"3. Luyện tập - Kiểm tra","gv":"- (10 phút) GV phát phiếu ôn tập gồm phần trắc nghiệm chọn đáp án đúng và phần nối cột nối tên thao tác với việc làm.\n- GV quy định thời gian làm bài, nhắc HS tự làm bài trước rồi mới đối chiếu đáp án.\n- Lỗi HS hay mắc và cách xử lí: nhầm nháy đúp với nháy một lần, GV cho HS làm lại thao tác trên máy chiếu; nhầm hàng phím trên với hàng phím dưới, GV cho HS chỉ lại trên hình bàn phím phóng to; quên tắt máy đúng cách, GV nhắc lại thứ tự các bước tắt máy.","hs":"- HS làm bài nghiêm túc, đúng thời gian quy định.\n- HS đổi phiếu, chấm chéo và tự đánh giá kết quả của mình.\n- HS nhận ra lỗi của mình, làm lại thao tác cho đúng và ghi nhớ."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS ghi vào vở hai điều em đã làm tốt và một điều em cần luyện thêm trong nửa học kì vừa qua.\n- GV mời vài HS chia sẻ và nêu cách luyện thêm ở nhà.\n- GV nhận xét chung, tuyên dương HS tiến bộ; dặn tiết sau vào phòng máy thực hành với tệp và thư mục.","hs":"- HS tự đánh giá và ghi lại điều mình đã làm tốt, điều cần cố gắng.\n- HS chia sẻ trước lớp và nghe góp ý của bạn.\n- HS ghi việc cần chuẩn bị cho tiết thực hành sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động ôn lại nửa đầu học kì: nối tên bộ phận máy tính với hình, sắp đúng thứ tự các bước bật máy và tắt máy, chọn cách sắp xếp giúp tìm đồ vật nhanh nhất; sau mỗi câu HS biết ngay đúng hay sai và làm lại đúng câu mình còn sai.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) HS mở lại hình đã vẽ bằng chuột và đoạn chữ đã gõ trong những tuần qua, chọn một sản phẩm để làm cho gọn và đẹp hơn rồi nói rõ mình đã sửa chỗ nào, vì sao sửa như thế.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép của bạn; chỉ mở thư mục và sản phẩm của mình, không mở, không sửa, không xoá bài của bạn; hết giờ tắt máy đúng cách rồi mới rời phòng máy.","hs":"- HS làm bài ôn tương tác và tự nhận ra phần kiến thức mình còn chưa chắc.\n- HS hoàn thiện được một sản phẩm số của mình và nói rõ đã sửa chỗ nào."}]},
{"lop":3,"mon":"Tin học","tuan":19,"tiet":19,"bai":"Bài 9: Thực hành với tệp và thư mục trong máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Tìm hiểu được cấu trúc cây của một thư mục để biết nó chứa những thư mục con, tệp nào.\n- Mở được cửa sổ làm việc với tệp và thư mục.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.3 CB1a: Xác định được cách tổ chức, lưu trữ và truy xuất dữ liệu, thông tin và nội dung một cách đơn giản trong môi trường số: HS mở được cửa sổ quản lí tệp và đi đúng đường tới thư mục cần tìm.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV nêu tình huống bạn An và bạn Khoa muốn tạo một thư mục để lưu ảnh gia đình trên máy tính, các em hãy giúp hai bạn.\n- GV chia nhóm 2 đến 3 HS một máy, dán số nhóm lên máy và quy định luân phiên, mỗi bạn thao tác 4 phút rồi đổi lượt.\n- GV nhắc nội quy phòng máy: ngồi đúng tư thế, không ăn uống cạnh máy, không tự ý rút dây, chưa được phép thì không xoá bất cứ thứ gì.","hs":"- HS hình dung công việc phải làm và sẵn sàng thực hành.\n- HS về đúng máy theo nhóm, nhớ lượt thực hành của mình.\n- HS nhắc lại nội quy phòng máy trước khi bắt đầu."},{"ten":"2. Khám phá - Thực hành: Mở cấu trúc thư mục","gv":"- (10 phút) GV làm mẫu trên máy chiếu: nháy đúp chuột trái vào biểu tượng This PC trên màn hình nền để mở cửa sổ làm việc với tệp và thư mục.\n- GV chỉ từng phần của cửa sổ: thanh địa chỉ ở phía trên, khung bên trái là cây thư mục, khung bên phải là các tệp và thư mục con.\n- GV làm mẫu nháy đúp vào ổ đĩa D, rồi nháy đúp vào một thư mục để đi sâu vào bên trong, sau đó nháy nút mũi tên lùi ở góc trên bên trái để quay ra.","hs":"- HS quan sát mẫu rồi tự nháy đúp vào biểu tượng This PC trên máy của nhóm.\n- HS gọi tên được các phần của cửa sổ: thanh địa chỉ, khung cây thư mục, khung nội dung.\n- HS mở được thư mục con và quay ra bằng nút mũi tên lùi."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV giao nhiệm vụ: mở thư mục của lớp trên ổ đĩa D, tìm thư mục mang tên tổ mình rồi đọc to xem bên trong có bao nhiêu tệp.\n- GV yêu cầu HS nhìn thanh địa chỉ và đọc thành lời đường đi từ ổ đĩa tới thư mục đang mở.\n- Lỗi HS hay mắc và cách xử lí: nháy đúp quá chậm nên chỉ chọn mà không mở được, GV đếm nhịp một hai thật nhanh cho HS bấm theo; nháy nhầm vào nút đóng cửa sổ, GV hướng dẫn mở lại bằng biểu tượng trên thanh công việc; đi lạc sang thư mục khác rồi loay hoay, GV chỉ cách bấm nút mũi tên lùi để quay lại chỗ cũ.","hs":"- HS luân phiên thực hành, tìm đúng thư mục theo yêu cầu và báo cáo số tệp bên trong.\n- HS đọc được đường đi hiện trên thanh địa chỉ.\n- HS nhận ra lỗi của mình, bấm nhanh hơn hoặc dùng nút lùi rồi làm lại cho đúng."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS nhìn biểu tượng của vài tệp trong thư mục và đoán tệp đó chứa chữ, chứa ảnh hay chứa âm thanh, sau đó mở thử một tệp để kiểm tra.\n- GV nhắc: chỉ mở xem trong thư mục GV chỉ định, không mở và không xoá tệp của bạn; gặp tệp lạ thì để nguyên và báo thầy cô.\n- GV hướng dẫn HS đóng cửa sổ, tắt máy đúng cách; dặn tiết sau học cách tạo, đổi tên và xoá thư mục.","hs":"- HS đoán nội dung tệp qua biểu tượng rồi mở thử để kiểm tra lại.\n- HS thực hiện đúng quy tắc chỉ xem, không sửa, không xoá.\n- HS tắt máy đúng cách, xếp lại ghế và chuột trước khi rời phòng máy."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV hướng dẫn từng bước để HS mở cửa sổ quản lí tệp, đi vào thư mục của lớp, mở một thư mục con rồi quay ngược trở ra bằng nút lùi; HS làm lại theo GV cho tới khi đi đúng đường mà không nhờ bạn chỉ.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS nhìn biểu tượng và phần đuôi tên tệp để đoán tệp đó chứa gì: tệp chữ, tệp ảnh, tệp âm thanh; HS mở thử một tệp để kiểm tra mình đoán có đúng không.\n⚠ (Miền 4: An toàn) Chỉ mở và xem trong thư mục GV chỉ định; không mở, không sửa, không xoá tệp của bạn và của máy; gặp tệp lạ không rõ của ai thì để nguyên và báo thầy cô.","hs":"- HS mở được cửa sổ quản lí tệp và đi đúng đường tới thư mục cần tìm.\n- HS đoán được nội dung tệp qua biểu tượng và kiểm tra lại bằng cách mở tệp."}]},
{"lop":3,"mon":"Tin học","tuan":20,"tiet":20,"bai":"Bài 9: Thực hành với tệp và thư mục trong máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được việc tạo, xoá, đổi tên thư mục.\n- Tìm được tệp ở thư mục cho trước theo yêu cầu.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS tạo, đặt tên, sao chép và di chuyển được tệp, thư mục của mình.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS nhắc lại cách mở cửa sổ làm việc với tệp và thư mục đã học ở tiết trước.\n- GV chia nhóm 2 đến 3 HS một máy như tiết trước, quy định luân phiên mỗi bạn 4 phút một lượt.\n- GV yêu cầu cả lớp cùng mở tới thư mục của lớp trên ổ đĩa D để chuẩn bị thực hành.","hs":"- HS nhắc lại: nháy đúp vào biểu tượng This PC trên màn hình nền.\n- HS về đúng máy, nhớ lượt của mình và ngồi đúng tư thế.\n- HS mở được cửa sổ và đi tới thư mục của lớp."},{"ten":"2. Khám phá - Thực hành: Thao tác với thư mục","gv":"- (10 phút) GV làm mẫu tạo thư mục mới: nháy nút phải chuột vào chỗ trống trong cửa sổ, chọn New rồi chọn Folder, gõ tên thư mục và bấm phím Enter.\n- GV làm mẫu đổi tên: nháy chuột trái chọn thư mục, nháy nút phải chọn Rename, gõ tên mới rồi bấm Enter.\n- GV làm mẫu xoá: chọn thư mục, bấm phím Delete và đọc kĩ câu hỏi xác nhận trước khi đồng ý; GV nhấn mạnh phải kiểm tra thật kĩ vì xoá nhầm có thể không lấy lại được.","hs":"- HS quan sát mẫu, ghi nhớ ba đường thao tác tạo, đổi tên và xoá thư mục.\n- HS làm theo trên máy của nhóm, tạo một thư mục mang tên mình.\n- HS đọc câu hỏi xác nhận trước khi xoá và biết dừng lại khi thấy không chắc."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV giao nhiệm vụ: trong thư mục của lớp, tạo cây thư mục theo mẫu gồm thư mục mang tên em, bên trong có hai thư mục con là Bai hoc và Hinh anh.\n- GV yêu cầu tìm một tệp GV đã để sẵn trong thư mục cho trước và nói rõ tệp đó nằm ở nhánh nào.\n- Lỗi HS hay mắc và cách xử lí: gõ xong tên thư mục nhưng quên bấm Enter nên tên không được lưu, GV nhắc bấm Enter hoặc nháy ra chỗ trống; đặt tên có dấu cách thừa hoặc để nguyên tên New folder, GV hướng dẫn đổi tên lại cho dễ hiểu; xoá nhầm thư mục, GV hướng dẫn bấm tổ hợp Ctrl và Z để huỷ thao tác vừa làm.","hs":"- HS luân phiên thực hành, tạo đúng cây thư mục theo mẫu.\n- HS tìm được tệp trong thư mục cho trước và chỉ đúng nhánh chứa tệp.\n- HS nhận ra lỗi của mình, bấm Enter để lưu tên hoặc dùng Ctrl và Z để lấy lại thư mục vừa xoá nhầm."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS sắp xếp các tệp bài học của mình vào đúng thư mục con vừa tạo bằng cách kéo thả tệp vào thư mục.\n- GV nhắc: đặt tên tệp theo nội dung, không đặt tên có họ tên đầy đủ và địa chỉ nhà; bài quan trọng nên lưu ở hai nơi.\n- GV hướng dẫn HS đóng cửa sổ và tắt máy đúng cách; dặn tiết sau học bài bảo vệ thông tin khi dùng máy tính.","hs":"- HS kéo thả tệp vào đúng thư mục, kiểm tra lại xem tệp đã nằm đúng chỗ chưa.\n- HS đặt tên tệp dễ hiểu và nêu được vì sao không đặt tên chứa thông tin riêng.\n- HS tắt máy đúng cách và xếp lại chỗ ngồi trước khi ra về."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS tạo một thư mục riêng mang tên mình trong thư mục của lớp, đặt tên tệp cho dễ hiểu rồi sao chép và di chuyển bài làm vào đúng thư mục ấy; làm nhầm thì dùng lệnh huỷ thao tác để quay lại.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) HS sắp lại toàn bộ bài làm của mình từ đầu năm vào thư mục riêng, đặt tên gọn và dễ hiểu, rồi thi tìm nhanh một bài bất kì theo yêu cầu của GV.\n⚠ (Miền 4: An toàn) Kiểm tra thật kĩ trước khi xoá vì tệp bị xoá có thể không lấy lại được; bài quan trọng nên lưu ở hai nơi; chỉ thao tác trong thư mục mang tên mình, không đụng vào thư mục của bạn.","hs":"- HS tạo, đặt tên, sao chép và di chuyển được tệp, thư mục của mình.\n- HS sắp xếp gọn bài làm của mình và tìm lại được nhanh."}]},
{"lop":3,"mon":"Tin học","tuan":21,"tiet":21,"bai":"Bài 10: Bảo vệ thông tin khi dùng máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết được thông tin cá nhân và gia đình có thể được lưu trữ, trao đổi nhờ máy tính.\n- Nhận biết những thông tin cần được bảo vệ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS chỉ ra được đâu là thông tin riêng không được cho người lạ.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV hỏi: những thông tin nào về em và gia đình đang được lưu trong máy tính hoặc điện thoại ở nhà?\n- GV ghi nhanh câu trả lời lên bảng thành một danh sách.\n- GV hỏi tiếp: trong danh sách này, thông tin nào em cho ai biết cũng được, thông tin nào phải giữ kín?","hs":"- HS kể: ảnh chụp, họ tên, ngày sinh, địa chỉ nhà, số điện thoại của bố mẹ.\n- HS quan sát danh sách trên bảng và suy nghĩ.\n- HS bước đầu tách được thông tin có thể nói ra và thông tin cần giữ kín."},{"ten":"2. Khám phá: Thông tin cần bảo vệ","gv":"- (12 phút) GV hướng dẫn nhận biết thông tin cần giữ kín: họ tên đầy đủ, ngày sinh, địa chỉ nhà, tên trường lớp, số điện thoại, mật khẩu, ảnh riêng của gia đình.\n- GV nêu câu hỏi: nếu người lạ biết địa chỉ nhà và giờ tan học của em thì có thể xảy ra điều gì?\n- Dự kiến HS trả lời: người xấu có thể đến tìm, có thể lừa em đi theo.\n- GV chốt: những thông tin đó là của riêng em và gia đình, không được cho người lạ biết dù họ hứa tặng quà.","hs":"- HS lắng nghe và nhắc lại các loại thông tin cần được bảo vệ.\n- HS trả lời câu hỏi, nêu nguy cơ có thể xảy ra.\n- HS đọc và ghi nhớ hộp kiến thức trong SGK."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu học tập có bảng hai cột: Có thể chia sẻ và Cần giữ kín; yêu cầu HS xếp các thẻ thông tin vào đúng cột.\n- Các thẻ gợi ý: món ăn em thích, số điện thoại của mẹ, tên con vật em nuôi, địa chỉ nhà, mật khẩu máy tính.\n- GV chữa bài, cho HS giải thích lí do xếp như vậy và sửa những chỗ còn nhầm.","hs":"- HS làm phiếu, xếp các thẻ thông tin vào đúng cột.\n- HS giải thích lí do lựa chọn của mình trước lớp.\n- HS sửa lại chỗ xếp nhầm sau khi nghe bạn và GV góp ý."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV nêu tình huống: một trang trên mạng hứa tặng quà nếu em điền số điện thoại và địa chỉ nhà, em sẽ làm gì?\n- GV chốt cách xử lí: không điền, tắt trang đó và kể ngay với bố mẹ hoặc thầy cô.\n- GV dặn về nhà nhắc người thân cùng giữ kín thông tin gia đình; dặn tiết sau học cách phòng tránh nguy cơ khi giao tiếp qua máy tính.","hs":"- HS chọn cách xử lí đúng và giải thích vì sao không nên điền thông tin.\n- HS nhắc lại: không điền, tắt trang và báo người lớn.\n- HS nhận nhiệm vụ về nhà và ghi việc chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu một phiếu đăng kí trên mạng có các ô họ tên, ngày sinh, địa chỉ nhà, số điện thoại của cha mẹ, ảnh chân dung; HS chỉ ra những ô nào là thông tin riêng của gia đình và nói vì sao không được điền cho người lạ.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV nêu vài tình huống: một trang hứa tặng quà nếu điền số điện thoại, một người lạ trong trò chơi hỏi tên trường; HS chọn cách xử lí đúng trong ba cách GV đưa ra rồi giải thích vì sao mình chọn như vậy.\n⚠ (Miền 4: An toàn) Không cho ai họ tên đầy đủ, ngày sinh, địa chỉ nhà, tên trường lớp, giờ tan học và ảnh riêng của mình; không nhận quà, không hẹn gặp người quen qua mạng; bị doạ nạt hay bị hỏi những điều khó chịu thì báo ngay cha mẹ, thầy cô hoặc gọi Tổng đài Quốc gia Bảo vệ trẻ em 111.","hs":"- HS chỉ ra được đâu là thông tin riêng không được cho người lạ.\n- HS chọn được cách xử lí đúng trước lời hứa tặng quà hay câu hỏi của người lạ."}]},
{"lop":3,"mon":"Tin học","tuan":22,"tiet":22,"bai":"Bài 10: Bảo vệ thông tin khi dùng máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Có ý thức bảo vệ thông tin cá nhân và gia đình khi giao tiếp qua máy tính.\n- Biết người xấu có thể lợi dụng thông tin để gây hại và cách phòng tránh.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 2.5 CB1a: Phân biệt được chuẩn mực hành vi đơn giản và biết cách sử dụng công nghệ số và tương tác trong môi trường số: HS nói được lời xin phép và lời từ chối đúng mực trên môi trường số.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV nêu tình huống: một người lạ trên mạng nhắn tin khen em dễ thương rồi hỏi tên trường và giờ tan học của em.\n- GV cho HS thảo luận cặp đôi trong 2 phút: em trả lời hay không trả lời, vì sao?\n- GV mời vài cặp nêu ý kiến rồi dẫn vào bài.","hs":"- HS thảo luận cặp đôi và nêu cách ứng xử của mình.\n- HS trả lời: không trả lời, không kết bạn với người lạ, kể lại cho bố mẹ.\n- HS lắng nghe ý kiến của bạn và bổ sung."},{"ten":"2. Khám phá: Phòng tránh nguy cơ","gv":"- (12 phút) GV hướng dẫn ba quy tắc: không chia sẻ thông tin riêng với người lạ; không nhận quà và không hẹn gặp người quen qua mạng; báo ngay người lớn khi gặp tình huống đáng ngờ.\n- GV nêu câu hỏi: vì sao người xấu lại muốn biết thông tin của em? Dự kiến HS trả lời: để lừa em, để làm phiền gia đình em.\n- GV giới thiệu Tổng đài Quốc gia Bảo vệ trẻ em số 111 để HS và gia đình gọi khi cần giúp đỡ.\n- GV chốt kiến thức và cho HS nhắc lại ba quy tắc.","hs":"- HS lắng nghe, nêu việc nên làm và không nên làm khi giao tiếp qua máy tính.\n- HS trả lời câu hỏi và nêu ví dụ mình từng gặp hoặc nghe kể.\n- HS ghi nhớ ba quy tắc và số điện thoại của tổng đài 111."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV chia nhóm 4, phát ba tình huống để HS chọn cách xử lí: người lạ xin kết bạn; có đường liên kết lạ hiện lên mời bấm vào; có người đòi em gửi ảnh riêng.\n- GV yêu cầu mỗi nhóm nói rõ em từ chối bằng lời thế nào và báo cho ai.\n- GV nhận xét, chốt cách xử lí an toàn và khen nhóm nói lời từ chối dứt khoát mà vẫn lịch sự.","hs":"- HS làm việc nhóm, chọn cách xử lí an toàn cho từng tình huống.\n- HS tập nói lời từ chối dứt khoát và lịch sự trước lớp.\n- HS nhận xét nhóm bạn và học thêm cách nói hay của bạn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: về nhà em hãy nhắc người thân cùng giữ an toàn thông tin, ví dụ không cho người lạ mượn điện thoại, không chụp ảnh giấy tờ gửi cho người lạ.\n- GV cho HS cùng lập bảng quy tắc an toàn của lớp để dán ở phòng máy.\n- GV dặn tiết sau vào phòng máy học cách tạo bài trình chiếu.","hs":"- HS nhận nhiệm vụ, nêu điều mình sẽ nói với người thân.\n- HS góp ý kiến để lập bảng quy tắc an toàn của lớp.\n- HS ghi việc cần chuẩn bị cho tiết thực hành sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS tập nói lời xin phép và lời từ chối trên môi trường số: muốn đưa ảnh có mặt bạn lên nhóm lớp thì phải hỏi bạn trước; ai đòi ảnh, đòi thông tin thì trả lời dứt khoát là không rồi kể lại ngay với người lớn.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS cùng GV lập bảng quy tắc an toàn của lớp khi dùng máy tính: khoá máy hoặc đóng bài khi rời chỗ, không cho ai mượn mật khẩu, không lưu bài vào máy của người khác; bảng được dán ngay tại phòng máy để cả lớp cùng theo.\n⚠ (Miền 4: An toàn) Không mở máy, không xem bài, không xem tin nhắn của người khác khi chưa được phép; biết mật khẩu của bạn cũng không được tự ý đăng nhập; không đăng ảnh có mặt bạn khi bạn chưa đồng ý.","hs":"- HS nói được lời xin phép và lời từ chối đúng mực trên môi trường số.\n- HS thực hiện được bảng quy tắc an toàn của lớp khi dùng máy tính."}]},
{"lop":3,"mon":"Tin học","tuan":23,"tiet":23,"bai":"Bài 11: Bài trình chiếu của em (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được biểu tượng của phần mềm trình chiếu và khởi động được phần mềm.\n- Tạo được tệp trình chiếu, thêm được trang chiếu mới.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS tạo được một trang chiếu có tiêu đề, nội dung ngắn và hình minh hoạ.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV chiếu một bài trình chiếu ngắn gồm ba trang có ảnh và chữ giới thiệu về lớp mình.\n- GV hỏi: mỗi trang có những gì, em có muốn tự làm một bài như thế không?\n- GV chia nhóm 2 đến 3 HS một máy, quy định luân phiên mỗi bạn thao tác 4 phút; nhắc nội quy phòng máy.","hs":"- HS quan sát và nêu: mỗi trang có một dòng tiêu đề, vài dòng chữ và một bức ảnh.\n- HS nêu mong muốn tự tạo bài trình chiếu của mình.\n- HS về đúng máy theo nhóm và nhắc lại nội quy phòng máy."},{"ten":"2. Khám phá - Thực hành: Khởi động và tạo tệp","gv":"- (10 phút) GV giới thiệu biểu tượng phần mềm trình chiếu trên màn hình nền và làm mẫu: nháy đúp chuột trái vào biểu tượng để khởi động phần mềm.\n- GV làm mẫu tạo tệp mới: chọn mẫu trang trắng, nháy vào ô tiêu đề rồi gõ chữ, nháy ra ngoài để kết thúc.\n- GV làm mẫu thêm trang chiếu mới: nháy nút New Slide trên thanh công cụ, hoặc nháy nút phải vào khung danh sách trang bên trái rồi chọn New Slide.","hs":"- HS nháy đúp mở được phần mềm trình chiếu trên máy của nhóm.\n- HS tạo được tệp mới và gõ được chữ vào ô tiêu đề.\n- HS thêm được trang chiếu mới bằng nút New Slide."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV giao nhiệm vụ: tạo bài trình chiếu gồm ba trang, trang một ghi tên em và lớp, trang hai ghi ba điều em thích, trang ba chèn một hình từ kho ảnh GV đã chuẩn bị.\n- GV hướng dẫn chèn hình: nháy thẻ Insert, chọn Pictures, chọn hình trong thư mục GV chỉ định rồi nháy Insert.\n- Lỗi HS hay mắc và cách xử lí: nháy đúp quá chậm nên phần mềm chưa mở, GV nhắc bấm nhanh hai lần liền và chờ vài giây cho máy mở; gõ chữ ra ngoài trang chiếu vì chưa nháy vào ô nội dung, GV hướng dẫn nháy vào khung chữ trước khi gõ; kéo hình làm méo hình vì kéo ở cạnh giữa, GV hướng dẫn kéo ở góc để hình không bị méo.","hs":"- HS luân phiên thực hành, tạo đủ ba trang chiếu theo yêu cầu.\n- HS chèn được hình vào trang chiếu và di chuyển hình cho ngay ngắn.\n- HS lưu thử bài bằng tổ hợp phím Ctrl và S để không mất công làm lại từ đầu.\n- HS nhận ra lỗi của mình, nháy đúng ô nội dung và kéo hình ở góc rồi làm lại."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV chiếu hai trang chiếu cùng nội dung, một trang chữ nhỏ kín đặc, một trang chữ to ít dòng và hỏi: trang nào em ngồi cuối lớp vẫn đọc được?\n- GV chốt cách trình bày: chữ to, mỗi trang chỉ vài dòng, hình rõ và đúng nội dung.\n- GV nhắc chỉ dùng hình trong kho ảnh GV chuẩn bị, không đưa họ tên đầy đủ và địa chỉ nhà lên trang chiếu; hướng dẫn tắt máy đúng cách, dặn tiết sau hoàn thiện và lưu bài.","hs":"- HS chọn trang dễ đọc và nêu lí do lựa chọn.\n- HS rút ra cách trình bày trang chiếu cho dễ nhìn.\n- HS tắt phần mềm, tắt máy đúng cách và ghi việc chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV hướng dẫn HS từng bước tạo bài trình chiếu: mở phần mềm, thêm một trang chiếu, nhập tiêu đề, nhập vài dòng nội dung ngắn, chèn một hình minh hoạ từ kho ảnh GV đã chuẩn bị.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu hai trang chiếu cùng nội dung — một trang chữ nhỏ và kín đặc, một trang chữ to và ít dòng; HS chọn trang mình đọc được từ cuối lớp và tự rút ra cách trình bày trang chiếu cho dễ nhìn.\n⚠ (Miền 4: An toàn) Chỉ dùng hình trong kho ảnh thầy cô đã chuẩn bị hoặc hình do chính mình vẽ; hình lấy từ nơi khác phải nói rõ lấy ở đâu, không nhận là của mình; không đưa họ tên đầy đủ, địa chỉ nhà lên trang chiếu.","hs":"- HS tạo được một trang chiếu có tiêu đề, nội dung ngắn và hình minh hoạ.\n- HS nêu được cách trình bày trang chiếu để người ngồi cuối lớp vẫn đọc được."}]},
{"lop":3,"mon":"Tin học","tuan":24,"tiet":24,"bai":"Bài 11: Bài trình chiếu của em (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Gõ được một vài dòng văn bản vào trang chiếu.\n- Lưu và đặt được tên cho tệp trình chiếu.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 3.2 CB1a: Chọn được các cách sửa đổi, tinh chỉnh, cải thiện và tích hợp các mục đơn giản có nội dung và thông tin mới để tạo ra những nội dung và thông tin mới và độc đáo: HS hoàn thiện, đặt tên và lưu được bài trình chiếu vào thư mục của mình.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV hướng dẫn HS mở lại tệp trình chiếu đã tạo ở tiết trước: nháy đúp vào biểu tượng tệp trong thư mục của lớp.\n- GV chia nhóm và quy định luân phiên như tiết trước để bạn nào cũng được thực hành.\n- GV nhắc HS ngồi đúng tư thế, mắt cách màn hình khoảng 50 cm.","hs":"- HS nháy đúp mở lại được tệp trình chiếu của mình.\n- HS về đúng máy, nhớ lượt thực hành của mình.\n- HS chỉnh lại ghế và khoảng cách ngồi cho đúng."},{"ten":"2. Khám phá - Thực hành: Gõ văn bản và lưu tệp","gv":"- (10 phút) GV hướng dẫn gõ văn bản: nháy chuột trái vào khung nội dung của trang chiếu rồi gõ, dùng phím Shift để viết hoa chữ đầu câu, phím Enter để xuống dòng, phím Backspace để xoá chữ sai.\n- GV làm mẫu lưu tệp: nháy thẻ File, chọn Save As, chọn thư mục mang tên em, gõ tên tệp dễ hiểu rồi nháy nút Save.\n- GV nhấn mạnh nên lưu lại nhiều lần trong khi làm bằng tổ hợp phím Ctrl và S để không mất bài khi máy tắt đột ngột.","hs":"- HS gõ được vài dòng văn bản vào trang chiếu, biết dùng Shift, Enter và Backspace.\n- HS lưu được tệp vào thư mục của mình với tên dễ hiểu.\n- HS tập bấm Ctrl và S để lưu nhanh trong lúc làm bài."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV giao nhiệm vụ: hoàn thiện bài trình chiếu giới thiệu bản thân hoặc gia đình gồm chữ và hình, mỗi trang chỉ vài dòng cho dễ đọc.\n- GV đi từng máy hỗ trợ HS còn lúng túng, nhắc các nhóm đổi lượt đúng giờ.\n- Lỗi HS hay mắc và cách xử lí: quên lưu bài nên mất công gõ lại, GV nhắc cả lớp cùng bấm Ctrl và S sau mỗi 5 phút; lưu đè lên bài của bạn vì chọn nhầm thư mục, GV hướng dẫn đọc kĩ tên thư mục trước khi nháy Save; bật Caps Lock nên cả dòng ra chữ hoa, GV chỉ đèn báo và hướng dẫn bấm lại phím Caps Lock một lần.","hs":"- HS luân phiên hoàn thiện bài trình chiếu của mình và lưu lại sản phẩm.\n- HS kiểm tra lại tên tệp và thư mục trước khi lưu.\n- HS nhận ra lỗi của mình, tắt Caps Lock, lưu bài đúng thư mục và làm lại cho đúng."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV mời vài HS trình chiếu sản phẩm bằng cách bấm phím F5 rồi dùng phím mũi tên để chuyển trang.\n- GV nêu ba tiêu chí nhận xét: chữ có dễ đọc không, hình có đúng nội dung không, bài đã lưu đúng thư mục chưa.\n- GV nhắc xin phép bạn trước khi đưa ảnh có mặt bạn vào bài; hướng dẫn tắt máy đúng cách và dặn nội dung tiết sau.","hs":"- HS trình chiếu sản phẩm của mình, chuyển trang bằng phím mũi tên.\n- HS nhận xét bài của bạn theo ba tiêu chí, góp ý bằng lời tử tế.\n- HS sửa lại bài theo góp ý, tắt máy đúng cách trước khi ra về."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) HS hoàn thiện bài trình chiếu của mình: sửa lại chữ cho gọn, chỉnh hình cho ngay ngắn, đặt tên tệp dễ hiểu rồi lưu vào thư mục mang tên mình để lần sau mở lại được.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) HS trình chiếu bài của mình cho nhóm xem và nghe bạn góp ý xem chữ có dễ đọc không, hình có đúng nội dung không; HS sửa lại theo góp ý và cảm ơn bạn đã góp ý cho mình.\n⚠ (Miền 4: An toàn) Muốn đưa ảnh có mặt bạn vào bài thì phải hỏi bạn trước; góp ý cho bài của bạn bằng lời tử tế, chê bai làm bạn ngại không dám trình bày nữa; lưu bài vào đúng thư mục của mình, không lưu đè lên bài của bạn.","hs":"- HS hoàn thiện, đặt tên và lưu được bài trình chiếu vào thư mục của mình.\n- HS trình bày bài trước nhóm, nghe góp ý và sửa lại sản phẩm."}]},
{"lop":3,"mon":"Tin học","tuan":25,"tiet":25,"bai":"Bài 12: Tìm hiểu về thế giới tự nhiên (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận thấy nhờ máy tính mà con người quan sát và biết thêm về thế giới tự nhiên một cách sinh động, trực quan.\n- Kể lại được những hiểu biết mới khi quan sát qua phần mềm.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được điều mình quan sát được nhờ phim tua nhanh và ảnh cận cảnh.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: em muốn tìm hiểu về loài vật, cây cối, biển sâu... làm cách nào để thấy rõ?","hs":"- HS chia sẻ; mong muốn quan sát qua máy tính."},{"ten":"2. Khám phá – Thực hành: Quan sát thế giới tự nhiên","gv":"- GV mở phần mềm/hình ảnh, video số về động vật, thực vật, hiện tượng tự nhiên cho HS quan sát.","hs":"- HS quan sát, nêu điều mới mẻ, thú vị đã thấy."},{"ten":"3. Luyện tập","gv":"- GV cho HS chọn một đối tượng tự nhiên, quan sát và kể lại đặc điểm.","hs":"- HS thực hành quan sát, kể lại hiểu biết mới."},{"ten":"4. Vận dụng","gv":"- GV: hãy nhờ người lớn cùng xem thêm một video về thiên nhiên phù hợp lứa tuổi.","hs":"- HS thực hiện ở nhà, chia sẻ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở kho ảnh và phim về thế giới tự nhiên: đoạn phim tua nhanh hạt nảy mầm trong nhiều ngày, ảnh cận cảnh cánh bướm, phim quay dưới đáy biển; HS thấy được những điều mà đứng trong sân trường quan sát cả buổi cũng không thấy được.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV chụp một chiếc lá trong sân trường rồi mở ứng dụng nhận diện cây cho cả lớp xem máy đoán tên; HS đối chiếu với hình trong sách và thấy máy có lúc đoán đúng, có lúc nhầm giữa hai loài giống nhau nên phải kiểm tra lại. GV thao tác hoàn toàn, HS quan sát và nhận xét.\n⚠ (Miền 4: An toàn) Kết quả máy đoán chỉ để tham khảo, tuyệt đối không dựa vào máy để kết luận cây hay quả có ăn được hay không; chỉ xem phim và ảnh thầy cô đã chọn sẵn, không tự tìm thêm; không hái lá, bẻ cành chỉ để chụp ảnh.","hs":"- HS nêu được điều mình quan sát được nhờ phim tua nhanh và ảnh cận cảnh.\n- HS nêu được kết quả ứng dụng đoán tên cây phải kiểm tra lại bằng sách và hỏi thầy cô."}]},
{"lop":3,"mon":"Tin học","tuan":26,"tiet":26,"bai":"Bài 13: Luyện tập sử dụng chuột (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Cầm chuột đúng cách; thực hiện thành thạo các thao tác: di chuyển, nháy, kéo thả, nháy nút phải, nháy đúp, dùng nút cuộn.\n- Nhận thấy phần mềm hướng dẫn thao tác đúng với chuột.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS làm thành thạo các thao tác chuột và đọc được kết quả phần mềm chấm.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS nhắc lại năm thao tác với chuột đã học và làm thử ngay trên máy của nhóm.\n- GV chia nhóm 2 HS một máy, quy định mỗi bạn luyện 5 phút rồi đổi lượt, bạn chưa tới lượt chỉ nhắc bằng lời chứ không giằng chuột.\n- GV kiểm tra cách cầm chuột của từng bạn: lòng bàn tay úp nhẹ, ngón trỏ ở nút trái, ngón giữa ở nút phải.","hs":"- HS nêu: di chuyển, nháy, nháy nút phải, nháy đúp, kéo thả và dùng nút cuộn.\n- HS về đúng máy, thoả thuận với bạn ai làm trước, đổi lượt lúc nào.\n- HS đặt tay lên chuột đúng cách theo hướng dẫn của GV."},{"ten":"2. Khám phá - Thực hành: Luyện thao tác chuột","gv":"- (10 phút) GV hướng dẫn HS nháy đúp vào biểu tượng phần mềm luyện chuột trên màn hình nền để khởi động.\n- GV giới thiệu từng phần luyện tập: phần nháy chọn mục tiêu, phần nháy đúp mở hộp quà, phần kéo thả mảnh ghép vào đúng chỗ, phần dùng nút cuộn để xem hết trang.\n- GV làm mẫu một lượt trên máy chiếu, vừa làm vừa nói rõ đang dùng thao tác nào.","hs":"- HS nháy đúp mở được phần mềm luyện chuột trên máy của nhóm.\n- HS quan sát mẫu và làm theo từng phần luyện tập.\n- HS gọi đúng tên thao tác mình đang dùng ở mỗi phần."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV tổ chức thi giữa các nhóm: mỗi bạn làm một lượt, phần mềm báo số việc làm đúng và thời gian hoàn thành, nhóm ghi kết quả vào phiếu.\n- GV yêu cầu HS nhìn kết quả để biết mình còn chậm ở thao tác nào rồi luyện lại đúng thao tác đó.\n- Lỗi HS hay mắc và cách xử lí: kéo thả nhả chuột sớm nên mảnh ghép rơi giữa đường, GV nhắc giữ chặt nút trái tới đúng chỗ mới nhả; nhấc chuột lên khỏi bàn khi rê nên con trỏ đứng yên, GV hướng dẫn rê nhẹ chuột trên mặt bàn; nháy đúp bằng hai ngón khác nhau nên máy không nhận, GV hướng dẫn dùng riêng ngón trỏ bấm hai lần thật nhanh.","hs":"- HS luân phiên thi, ghi lại số việc đúng và thời gian của mình vào phiếu.\n- HS nhận ra thao tác mình còn chậm và luyện lại đúng thao tác đó.\n- HS sửa lỗi kéo thả và nháy đúp theo hướng dẫn rồi làm lại đạt kết quả tốt hơn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS dùng chuột vẽ một hình đơn giản trong phần mềm vẽ: kéo để tạo nét, nháy để chọn màu, kéo thả để di chuyển hình.\n- GV nhắc giữ gìn thiết bị: cầm chuột nhẹ tay, không giật dây, không đập chuột xuống bàn; nghỉ tay và duỗi các ngón sau mỗi 20 phút.\n- GV dặn nếu ở nhà có máy thì luyện thêm cho thành thạo; hướng dẫn tắt phần mềm và tắt máy đúng cách.","hs":"- HS vẽ được một hình đơn giản bằng chuột và tô màu theo ý thích.\n- HS thực hiện đúng các quy tắc giữ gìn thiết bị và nghỉ tay đúng lúc.\n- HS tắt phần mềm, tắt máy đúng cách và xếp lại chỗ ngồi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS luyện thao tác chuột qua phần mềm có chấm điểm: kéo thả, nháy đúp, vẽ theo mẫu; sau mỗi lượt máy báo số việc làm đúng và thời gian, HS nhìn kết quả để biết mình còn chậm ở thao tác nào rồi luyện lại đúng thao tác đó.\n- (Miền 2: Giao tiếp và hợp tác trong môi trường số — Cơ bản, bậc 1) Hai HS dùng chung một máy: thoả thuận trước ai làm trước và làm bao lâu thì đổi lượt; bạn ngồi cạnh chỉ nhắc bằng lời chứ không giằng chuột, thắng thua đều giữ thái độ vui vẻ.\n⚠ (Miền 4: An toàn) Chỉ chơi phần mềm và đúng khoảng thời gian thầy cô cho phép, hết lượt là nhường bạn; không mở trò chơi khác trong giờ; cầm chuột nhẹ tay, nghỉ tay và nhìn ra xa sau mỗi 20 phút.","hs":"- HS làm thành thạo các thao tác chuột và đọc được kết quả phần mềm chấm.\n- HS dùng chung máy với bạn theo đúng thoả thuận, giữ thái độ vui vẻ."}]},
{"lop":3,"mon":"Tin học","tuan":27,"tiet":27,"bai":"Ôn tập, kiểm tra học kì (Chủ đề E)","yccd":"1. Năng lực Tin học (đặc thù):\n- Củng cố kĩ năng thực hành: tạo bài trình chiếu, quan sát thế giới tự nhiên qua phần mềm, luyện chuột.\n- Vận dụng làm bài kiểm tra thực hành/trắc nghiệm, tự đánh giá.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV tổ chức hỏi đáp nhanh bằng hình thức Truyền điện để ôn lại kiến thức và kĩ năng đã học trong chủ đề.\n- Các câu hỏi gợi ý: muốn mở một biểu tượng thì dùng thao tác chuột nào, muốn lưu bài thì bấm tổ hợp phím nào, hai phím có gai trên bàn phím là phím nào?\n- GV phổ biến hình thức ôn tập và kiểm tra của tiết học, chia nhóm 2 đến 3 HS một máy và nhắc nội quy phòng máy.","hs":"- HS tham gia trò chơi, trả lời nhanh rồi chỉ bạn tiếp theo.\n- HS trả lời: nháy đúp để mở, bấm Ctrl và S để lưu, hai phím có gai là F và J.\n- HS về đúng máy theo nhóm, nhắc lại nội quy phòng máy trước khi làm bài."},{"ten":"2. Ôn tập","gv":"- (10 phút) GV hệ thống lại các kĩ năng đã học theo bốn nhóm: thao tác chuột, thao tác bàn phím, tạo và lưu tệp trình chiếu, tổ chức tệp và thư mục.\n- GV cho HS nhắc lại quy trình từng việc: mở phần mềm bằng cách nháy đúp biểu tượng trên màn hình nền; lưu bài bằng File rồi Save As rồi chọn thư mục và gõ tên tệp; tạo thư mục bằng nháy nút phải rồi chọn New và Folder.\n- GV làm mẫu lại trên máy chiếu những thao tác lớp còn lúng túng, nhấn mạnh thứ tự các bước tắt máy đúng cách.","hs":"- HS nhắc lại quy trình từng thao tác theo yêu cầu của GV.\n- HS nêu được đường đi cụ thể để lưu bài và để tạo thư mục mới.\n- HS quan sát mẫu và làm thử lại trên máy của nhóm mình."},{"ten":"3. Luyện tập - Kiểm tra","gv":"- (12 phút) GV phát đề kiểm tra gồm phần trắc nghiệm trên phiếu và phần thực hành trên máy: tạo một thư mục mang tên em, tạo một bài trình chiếu hai trang có tiêu đề và một hình, lưu vào thư mục vừa tạo.\n- GV quy định thời gian, nhắc HS tự làm bài, không mở bài của bạn và không nhắc bài cho nhau.\n- Lỗi HS hay mắc và cách xử lí: quên lưu bài nên khi hết giờ chưa có sản phẩm, GV nhắc cả lớp lưu bài khi còn 5 phút; lưu nhầm sang thư mục khác, GV hướng dẫn đọc lại tên thư mục trên thanh địa chỉ trước khi nháy Save; gõ ra chữ hoa toàn dòng do bật Caps Lock, GV hướng dẫn bấm lại phím đó rồi gõ lại.","hs":"- HS làm bài trắc nghiệm và phần thực hành trên máy một cách trung thực.\n- HS tạo được thư mục, tạo và lưu được bài trình chiếu đúng yêu cầu.\n- HS nhận ra lỗi của mình, lưu lại bài đúng thư mục và sửa chỗ gõ sai."},{"ten":"4. Vận dụng - Nhận xét","gv":"- (8 phút) GV thu phiếu, kiểm tra nhanh sản phẩm trên vài máy và chiếu lên cho cả lớp cùng xem.\n- GV nêu ba tiêu chí nhận xét: thao tác đúng và nhanh, sản phẩm lưu đúng thư mục, giữ gìn thiết bị và trật tự trong giờ.\n- GV nhận xét chung, tuyên dương HS tiến bộ; hướng dẫn HS tắt máy đúng cách, xếp lại ghế và dặn nội dung học tiếp theo.","hs":"- HS nộp bài đúng giờ và cùng xem sản phẩm của bạn trên máy chiếu.\n- HS tự đánh giá bài của mình theo ba tiêu chí và nhận xét bài của bạn.\n- HS tắt máy đúng cách, xếp lại ghế, chuột và bàn phím trước khi rời phòng máy."}]},
{"lop":3,"mon":"Tin học","tuan":28,"tiet":28,"bai":"Bài 14: Em thực hiện công việc như thế nào (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được một số công việc hằng ngày có thể thực hiện theo từng bước, các bước sắp xếp theo thứ tự.\n- Sắp xếp được các bước của một công việc quen thuộc.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS sắp được các bước của một việc theo đúng thứ tự và tự phát hiện chỗ xếp sai.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV nêu: để pha một cốc nước cam, em phải làm những việc gì và theo thứ tự nào?\n- GV ghi các bước HS nêu lên bảng nhưng cố ý ghi lộn xộn rồi hỏi: làm theo thứ tự này có được không?\n- GV dẫn vào bài: một công việc gồm nhiều bước và các bước phải sắp đúng thứ tự.","hs":"- HS kể các bước: lấy cốc, vắt cam, cho đường, rót nước, khuấy đều.\n- HS phát hiện thứ tự trên bảng bị lộn xộn và nêu cách sắp lại.\n- HS nhận ra làm sai thứ tự thì kết quả không như mong muốn."},{"ten":"2. Khám phá: Công việc gồm nhiều bước","gv":"- (12 phút) GV hướng dẫn: mỗi công việc gồm nhiều bước, mỗi bước là một việc nhỏ, các bước phải được sắp xếp theo đúng thứ tự trước sau.\n- GV nêu câu hỏi: khi gấp một chiếc thuyền giấy, nếu làm bước cuối trước thì có ra chiếc thuyền không, vì sao?\n- Dự kiến HS trả lời: không được, vì bước sau chỉ làm được khi bước trước đã xong.\n- GV chốt kiến thức và cho HS đọc lại hộp ghi nhớ trong SGK.","hs":"- HS lắng nghe, nêu thêm ví dụ công việc gồm nhiều bước như quét lớp, gấp quần áo.\n- HS trả lời câu hỏi và giải thích vì sao phải theo đúng thứ tự.\n- HS đọc và ghi nhớ hộp kiến thức."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát cho mỗi nhóm 4 một bộ thẻ ghi các bước bị đảo lộn của một công việc quen thuộc như đánh răng, gấp áo, chuẩn bị cặp sách.\n- GV yêu cầu nhóm sắp lại các thẻ theo đúng thứ tự rồi dán lên bảng nhóm.\n- GV cho các nhóm đọc lại bài của nhau, chỉ ra chỗ xếp chưa hợp lí và giải thích.","hs":"- HS làm việc nhóm, sắp lại các thẻ theo đúng thứ tự các bước.\n- HS dán bài lên bảng nhóm và trình bày trước lớp.\n- HS nhận xét bài nhóm bạn, chỉ ra chỗ xếp sai và nêu cách sửa."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy ghi lại các bước của một việc em thường làm ở nhà rồi đọc cho người thân nghe xem có thiếu bước nào không.\n- GV liên hệ: máy tính cũng chỉ làm đúng khi con người chỉ rõ từng bước và đúng thứ tự.\n- GV dặn tiết sau học cách chia một việc lớn thành những việc nhỏ hơn.","hs":"- HS nhận nhiệm vụ, chọn một việc quen thuộc và phác nhanh các bước ra nháp.\n- HS liên hệ được việc sắp thứ tự các bước với cách máy tính làm việc.\n- HS ghi việc cần chuẩn bị cho tiết học sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu các thẻ việc của một công việc quen thuộc — pha một cốc nước chanh, gấp một chiếc thuyền giấy — theo thứ tự lộn xộn; HS kéo thả để sắp lại cho đúng rồi bấm nút chạy thử: máy diễn lại theo đúng thứ tự HS xếp nên HS thấy ngay chỗ mình xếp sai.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS xem đoạn phim hướng dẫn làm một việc, tạm dừng ở mỗi bước và ghi lại thành dãy các bước; HS nhận ra tua chậm và xem lại được là điều lời kể miệng một lần không cho phép.\n⚠ (Miền 4: An toàn) Chỉ kéo thả trong bài tập GV đã mở, không đổi cài đặt máy; xem phim hướng dẫn xong phải hỏi thầy cô trước khi làm thử ở nhà; không làm theo các đoạn phim hướng dẫn nguy hiểm thấy trên mạng.","hs":"- HS sắp được các bước của một việc theo đúng thứ tự và tự phát hiện chỗ xếp sai.\n- HS ghi lại được dãy các bước từ một đoạn phim hướng dẫn."}]},
{"lop":3,"mon":"Tin học","tuan":29,"tiet":29,"bai":"Bài 14: Em thực hiện công việc như thế nào (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được nên chia một việc thành những việc nhỏ hơn để dễ hiểu, dễ thực hiện.\n- Nêu được ví dụ về một việc có thể chia thành những việc nhỏ hơn.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS viết được dãy các bước đủ rõ để bạn làm theo đúng.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV nêu công việc lớn: lớp mình chuẩn bị một buổi liên hoan cuối năm, một mình em làm hết có được không?\n- GV hỏi tiếp: nên làm thế nào cho dễ và nhanh hơn?\n- GV ghi các ý kiến lên bảng và dẫn vào bài.","hs":"- HS trả lời: một mình làm hết thì rất lâu và dễ quên việc.\n- HS đề xuất chia thành các việc nhỏ và phân công cho từng tổ.\n- HS kể các việc nhỏ mình nghĩ ra: trang trí lớp, chuẩn bị bánh kẹo, chuẩn bị tiết mục."},{"ten":"2. Khám phá: Chia việc lớn thành việc nhỏ","gv":"- (12 phút) GV hướng dẫn cách chia một việc lớn thành các việc nhỏ hơn, mỗi việc nhỏ lại có thể chia tiếp nếu vẫn còn khó.\n- GV nêu câu hỏi: việc trang trí lớp có thể chia tiếp thành những việc nào nữa?\n- Dự kiến HS trả lời: cắt hoa giấy, viết bảng chào mừng, treo dây cờ.\n- GV chốt: chia nhỏ thì việc nào cũng dễ hiểu, dễ làm và dễ phân công cho từng người.","hs":"- HS lắng nghe và nêu thêm ví dụ về việc có thể chia nhỏ.\n- HS trả lời câu hỏi, chia tiếp việc trang trí lớp thành các việc nhỏ hơn.\n- HS đọc và ghi nhớ hộp kiến thức trong SGK."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV chia nhóm 4, giao mỗi nhóm một công việc như tổ chức sinh nhật, làm một tấm thiệp, chuẩn bị đi tham quan.\n- GV yêu cầu nhóm chia công việc đó thành các việc nhỏ, đánh số thứ tự rồi ghi vào phiếu học tập.\n- GV nhận xét bài các nhóm, chỉ ra chỗ còn thiếu bước hoặc bước ghi chưa rõ.","hs":"- HS làm việc nhóm, chia công việc thành các việc nhỏ và đánh số thứ tự.\n- HS trình bày phiếu của nhóm mình trước lớp.\n- HS nhận xét nhóm bạn, bổ sung bước còn thiếu."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy chia công việc chuẩn bị đi học buổi sáng của em thành các bước rồi đọc cho bạn cùng bàn làm theo.\n- GV lưu ý: chỗ nào bạn làm sai nghĩa là bước đó em viết còn thiếu hoặc chưa rõ, phải sửa lại cho rõ hơn.\n- GV dặn tiết sau học về công việc được thực hiện theo điều kiện.","hs":"- HS chia công việc thành các bước và đọc cho bạn cùng bàn làm theo.\n- HS sửa lại những bước bạn chưa hiểu cho rõ ràng hơn.\n- HS ghi việc cần chuẩn bị cho tiết học sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS viết dãy các bước cho một việc của mình rồi đọc cho bạn làm theo đúng từng chữ; chỗ nào bạn làm sai thì HS biết bước đó viết còn thiếu hoặc còn mơ hồ và sửa lại cho rõ.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV liên hệ: máy tính và rô-bốt cũng chỉ làm được việc khi con người chia việc thành các bước thật rõ và xếp đúng thứ tự; GV chiếu đoạn phim rô-bốt thực hiện lần lượt từng bước để HS thấy máy làm đúng như người đã dặn, dặn sai thì máy làm sai.\n⚠ (Miền 4: An toàn) Đọc bước cho bạn bằng lời rõ ràng, tử tế, không cười khi bạn làm sai; không làm theo bất cứ đoạn phim nào có lửa, dao, điện khi chưa có người lớn bên cạnh.","hs":"- HS viết được dãy các bước đủ rõ để bạn làm theo đúng.\n- HS nêu được máy chỉ làm đúng khi con người chia việc thành các bước rõ ràng."}]},
{"lop":3,"mon":"Tin học","tuan":30,"tiet":30,"bai":"Bài 15: Công việc được thực hiện theo điều kiện (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết một việc có được thực hiện hay không tuỳ thuộc vào điều kiện.\n- Nhận biết điều kiện trong tình huống quen thuộc.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS nhận ra kết quả thay đổi theo điều kiện khi thử trên bài tập tương tác.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV nêu: nếu trời mưa thì em mang áo mưa, nếu trời nắng thì em đội mũ; việc em làm phụ thuộc vào điều gì?\n- GV hỏi thêm: hôm nay trời thế nào, vậy sáng nay em đã mang theo gì?\n- GV dẫn vào bài: có những việc chỉ được thực hiện khi có một điều kiện nào đó.","hs":"- HS trả lời: việc em làm phụ thuộc vào thời tiết.\n- HS liên hệ với thời tiết hôm nay và đồ mình mang theo.\n- HS bước đầu nhận ra mối liên hệ giữa điều kiện và việc làm."},{"ten":"2. Khám phá: Công việc theo điều kiện","gv":"- (12 phút) GV hướng dẫn: một việc có được thực hiện hay không tuỳ thuộc vào điều kiện; điều kiện đúng thì làm, điều kiện không đúng thì không làm hoặc làm việc khác.\n- GV nêu thêm ví dụ: nếu đèn đỏ thì dừng lại, nếu học xong bài thì được xem hoạt hình, nếu trống đánh thì xếp hàng vào lớp.\n- GV nêu câu hỏi: trong câu nếu học xong bài thì được xem hoạt hình, đâu là điều kiện, đâu là việc làm?\n- GV chốt kiến thức và cho HS đọc hộp ghi nhớ trong SGK.","hs":"- HS lắng nghe và nêu thêm ví dụ công việc phụ thuộc điều kiện.\n- HS chỉ ra: điều kiện là học xong bài, việc làm là được xem hoạt hình.\n- HS đọc và ghi nhớ hộp kiến thức."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu học tập có năm tình huống, yêu cầu HS gạch chân điều kiện và khoanh tròn việc được thực hiện.\n- GV tổ chức trò chơi Nếu thì: GV đọc vế điều kiện, tổ nào giơ tay nhanh và nêu đúng vế việc làm thì được điểm.\n- GV chữa bài, sửa cho HS còn nhầm giữa vế điều kiện và vế việc làm.","hs":"- HS làm phiếu, gạch chân điều kiện và khoanh tròn việc được thực hiện.\n- HS tham gia trò chơi, nêu nhanh vế việc làm tương ứng.\n- HS tự sửa chỗ nhầm sau khi nghe GV chữa bài."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy tìm quanh em những việc chỉ xảy ra khi có điều kiện, ví dụ đèn đường sáng khi trời tối, chuông báo khi hết giờ.\n- GV cho HS ghi lại thành các câu có dạng nếu và thì vào phiếu học tập.\n- GV dặn tiết sau học cách diễn đạt bằng mẫu câu nếu và thì; nhắc HS không tự chạm vào công tắc, ổ điện ở lớp và ở nhà.","hs":"- HS tìm và kể được vài việc xảy ra theo điều kiện quanh mình.\n- HS ghi được các câu dạng nếu và thì vào phiếu học tập.\n- HS nhắc lại quy tắc an toàn khi ở gần thiết bị điện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV chiếu bài tập tương tác dạng Nếu… thì…: chọn điều kiện trời mưa thì hình cậu bé cầm ô, chọn điều kiện trời nắng thì hình cậu bé đội mũ; HS đổi điều kiện và xem kết quả đổi theo ngay trên màn hình nên hiểu được điều kiện quyết định việc làm.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS tìm trong đời sống những việc chỉ xảy ra khi có điều kiện: đèn đường sáng khi trời tối, chuông báo khi hết giờ; HS ghi lại thành các câu Nếu… thì… vào phiếu học tập.\n⚠ (Miền 4: An toàn) Chỉ mở bài tập GV đã chuẩn bị sẵn trên máy, không mở trang khác; ghi chép vào phiếu của mình, không chép của bạn; nghỉ mắt sau mỗi 20 phút nhìn màn hình.","hs":"- HS nhận ra kết quả thay đổi theo điều kiện khi thử trên bài tập tương tác.\n- HS ghi được các câu Nếu… thì… từ những việc quen thuộc quanh mình."}]},
{"lop":3,"mon":"Tin học","tuan":31,"tiet":31,"bai":"Bài 15: Công việc được thực hiện theo điều kiện (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Sử dụng được cách nói \"Nếu... thì...\" để diễn đạt một việc có được thực hiện hay không tuỳ thuộc điều kiện.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS đặt và chạy thử được câu Nếu… thì… của mình, sửa lại khi máy báo chưa đủ.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- GV: Phiếu học tập, thẻ Đ và S cho trò chơi củng cố, nam châm gắn bảng, bảng nhóm.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.\n- HS: Ôn lại bài tiết trước; giữ trật tự, không tự ý chạm vào máy tính và máy chiếu của GV.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV cho HS đặt câu theo mẫu nếu và thì với một tình huống quen thuộc trong sinh hoạt hằng ngày.\n- GV làm mẫu một câu: nếu trời mưa thì em mang áo mưa đi học.\n- GV mời lần lượt vài HS đặt câu và ghi nhanh lên bảng.","hs":"- HS đặt câu theo mẫu về sinh hoạt hằng ngày của mình.\n- HS nêu ví dụ: nếu em thức dậy muộn thì em phải đi học vội.\n- HS nghe câu của bạn và nhận xét câu nào đã đủ hai vế."},{"ten":"2. Khám phá: Diễn đạt điều kiện","gv":"- (12 phút) GV hướng dẫn mẫu diễn đạt gồm hai vế: vế đầu nêu điều kiện, vế sau nêu việc làm; thiếu một vế thì câu chưa rõ.\n- GV nêu câu hỏi: câu nếu trời nắng thì đã đủ chưa, còn thiếu gì? Dự kiến HS trả lời: thiếu vế việc làm nên chưa biết phải làm gì.\n- GV cho HS sửa vài câu còn thiếu vế trên bảng cho đủ hai phần.\n- GV chốt: diễn đạt đủ hai vế thì người nghe và cả máy tính mới hiểu và làm đúng.","hs":"- HS lắng nghe, chỉ ra hai vế trong mỗi câu mẫu.\n- HS trả lời và bổ sung vế còn thiếu cho các câu trên bảng.\n- HS ghi nhớ mẫu diễn đạt đầy đủ hai vế."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV phát phiếu học tập, yêu cầu HS viết bốn câu theo mẫu cho các tình huống cho trước: trời tối, hết giờ ra chơi, làm xong bài tập, gặp đèn đỏ.\n- GV cho HS đổi phiếu, đọc câu của bạn và đánh dấu câu nào còn thiếu vế.\n- GV chữa một số câu trước lớp, khen câu diễn đạt rõ ràng và ngắn gọn.","hs":"- HS viết bốn câu vào phiếu học tập theo đúng mẫu.\n- HS đổi phiếu, kiểm tra chéo và đánh dấu câu còn thiếu vế.\n- HS sửa lại câu của mình cho đủ hai vế và đọc trước lớp."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV giao: hãy nêu hai việc ở nhà em thực hiện theo điều kiện bằng mẫu câu vừa học và kể lại cho người thân nghe.\n- GV liên hệ: các thiết bị thông minh như cửa tự mở, quạt tự tắt cũng hoạt động theo những câu điều kiện do con người viết sẵn.\n- GV dặn tiết sau vào phòng máy học bài công việc của em và sự trợ giúp của máy tính.","hs":"- HS nêu được hai việc ở nhà theo mẫu câu điều kiện.\n- HS liên hệ được với hoạt động của các thiết bị thông minh quen thuộc.\n- HS ghi việc cần chuẩn bị cho tiết học sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS tự đặt các câu Nếu… thì… cho việc của mình rồi ghép vào bài tập trên máy và chạy thử; câu nào đặt còn thiếu vế thì máy không chạy được, HS sửa lại rồi chạy tiếp cho tới khi đúng.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV chiếu ví dụ các thiết bị thông minh hoạt động theo điều kiện: cửa tự mở khi có người đến gần, quạt tự tắt khi phòng đủ mát; GV nói rõ đó là những câu Nếu… thì… mà người lập trình đã viết sẵn cho máy, máy không tự nghĩ ra.\n⚠ (Miền 4: An toàn) Không tự chạm vào công tắc, ổ điện, thiết bị tự động ở trường và ở nhà; không làm theo các đoạn phim tự chế thiết bị điện trên mạng; thấy thiết bị chạy khác thường phải báo người lớn.","hs":"- HS đặt và chạy thử được câu Nếu… thì… của mình, sửa lại khi máy báo chưa đủ.\n- HS nêu được thiết bị thông minh hoạt động theo điều kiện do con người viết sẵn."}]},
{"lop":3,"mon":"Tin học","tuan":32,"tiet":32,"bai":"Bài 16: Công việc của em và sự trợ giúp của máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Phát biểu được nhiệm vụ đặt ra: xác định cái đã cho, cần làm gì, cần tạo ra sản phẩm số nào.\n- Chia được một công việc thành những việc nhỏ hơn, trong đó có việc thực hiện với trợ giúp của máy tính.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.2 CB1b: Nhận ra được các công cụ số đơn giản và các giải pháp công nghệ có thể có để giải quyết những nhu cầu đó: HS chỉ ra được việc nào trong nhiệm vụ của mình cần đến máy tính.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV nêu nhiệm vụ: cả lớp sẽ làm một tờ giới thiệu hoặc một bài trình chiếu ngắn về con vật em yêu thích.\n- GV hỏi: em đã có sẵn những gì, em cần làm gì và sản phẩm cuối cùng là gì?\n- GV chia nhóm 2 đến 3 HS một máy, quy định luân phiên và nhắc nội quy phòng máy.","hs":"- HS xác định: đã biết tên con vật và vài điều về nó, cần tìm thêm ảnh và gõ chữ.\n- HS nêu sản phẩm cuối cùng là một tờ giới thiệu hoặc bài trình chiếu ngắn.\n- HS về đúng máy theo nhóm và nhắc lại nội quy phòng máy."},{"ten":"2. Khám phá: Xác định và chia nhiệm vụ","gv":"- (10 phút) GV hướng dẫn cách phát biểu nhiệm vụ theo ba ý: cái đã cho, việc cần làm, sản phẩm cần tạo ra.\n- GV cùng HS chia nhiệm vụ thành các việc nhỏ: chọn con vật, tìm ảnh, viết vài câu giới thiệu, gõ chữ, chèn ảnh, lưu bài.\n- GV nêu câu hỏi: việc nào em làm bằng tay, việc nào máy tính giúp được nhanh hơn? Dự kiến HS trả lời: nghĩ nội dung thì em làm, còn gõ chữ, chèn ảnh và sửa đi sửa lại thì máy tính giúp nhanh hơn.","hs":"- HS phát biểu nhiệm vụ của mình theo đủ ba ý.\n- HS chia nhiệm vụ thành các việc nhỏ và ghi vào phiếu học tập.\n- HS chỉ ra được việc nào cần đến máy tính và giải thích vì sao."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV cho HS lập kế hoạch các bước cho nhiệm vụ của mình, đánh số thứ tự từ bước một đến bước cuối.\n- GV hướng dẫn HS mở kho ảnh và kho bài đọc GV đã chuẩn bị sẵn trên máy: nháy đúp vào thư mục Tu lieu trên màn hình nền, xem ảnh rồi ghi lại tên ảnh mình chọn.\n- Lỗi HS hay mắc và cách xử lí: nháy đúp quá chậm nên không mở được thư mục, GV đếm nhịp cho HS bấm nhanh hơn; mở nhầm thư mục khác rồi loay hoay, GV chỉ cách bấm nút mũi tên lùi để quay lại; chép luôn cả bài của bạn, GV nhắc mỗi bạn tự chọn nội dung của mình và ghi rõ ảnh lấy ở đâu.","hs":"- HS lập được kế hoạch các bước và trình bày trước nhóm.\n- HS mở đúng thư mục tư liệu, chọn ảnh và câu chữ hợp với nội dung của mình.\n- HS nhận ra lỗi của mình, dùng nút lùi để quay lại và tự chọn nội dung riêng."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho HS đọc lại kế hoạch của mình và kiểm tra xem còn thiếu bước nào không.\n- GV nhắc: chỉ lấy ảnh và bài đọc trong kho GV đã chuẩn bị, lấy ở đâu phải nói rõ ở đó; không tự tìm trên mạng khi chưa có GV bên cạnh.\n- GV hướng dẫn tắt máy đúng cách; dặn tiết sau thực hiện kế hoạch để tạo ra sản phẩm hoàn chỉnh.","hs":"- HS đọc lại kế hoạch, bổ sung bước còn thiếu.\n- HS nêu được nguồn của ảnh và bài đọc mình đã chọn.\n- HS tắt máy đúng cách và ghi việc cần chuẩn bị cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cùng HS lập bảng cho một việc cụ thể của lớp — làm tờ giới thiệu góc thư viện: việc nào cần làm bằng tay, việc nào máy tính giúp được nhanh hơn như gõ chữ, chèn ảnh, sửa đi sửa lại nhiều lần mà trang giấy vẫn sạch.\n- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) HS tìm tư liệu cho sản phẩm của mình trong kho ảnh và kho bài đọc GV đã chuẩn bị sẵn trên máy, chọn ra ảnh và câu chữ hợp với nội dung, ghi lại mình lấy ở đâu.\n⚠ (Miền 4: An toàn) Chỉ lấy ảnh và bài đọc trong kho thầy cô đã chuẩn bị; lấy ở đâu phải nói rõ ở đó, không nhận là của mình; không tìm thêm trên mạng khi chưa có thầy cô bên cạnh.","hs":"- HS chỉ ra được việc nào trong nhiệm vụ của mình cần đến máy tính.\n- HS chọn được ảnh và câu chữ hợp nội dung từ kho tư liệu và nói rõ nguồn."}]},
{"lop":3,"mon":"Tin học","tuan":33,"tiet":33,"bai":"Bài 16: Công việc của em và sự trợ giúp của máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được nhiệm vụ do giáo viên đặt ra, có sử dụng máy tính.\n- Tạo được một sản phẩm số đơn giản hoàn chỉnh.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 3.1 CB1a: Xác định được các cách tạo và chỉnh sửa nội dung đơn giản ở các định dạng đơn giản: HS hoàn thành và lưu được một sản phẩm số của mình, giới thiệu trước lớp.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS nhắc lại nhiệm vụ và kế hoạch các bước đã lập ở tiết trước.\n- GV chia nhóm và quy định luân phiên như tiết trước, mỗi bạn thao tác 5 phút rồi đổi lượt.\n- GV nhắc HS ngồi đúng tư thế, mắt cách màn hình khoảng 50 cm và nghỉ mắt khi thấy mỏi.","hs":"- HS nhắc lại nhiệm vụ và các bước trong kế hoạch của mình.\n- HS về đúng máy, nhớ lượt thực hành của mình.\n- HS chỉnh lại ghế và khoảng cách ngồi cho đúng."},{"ten":"2. Khám phá - Thực hành: Thực hiện nhiệm vụ","gv":"- (12 phút) GV hướng dẫn HS mở phần mềm trình chiếu bằng cách nháy đúp biểu tượng trên màn hình nền, tạo trang chiếu và gõ tiêu đề.\n- GV hướng dẫn chèn ảnh: nháy thẻ Insert, chọn Pictures, mở thư mục Tu lieu, chọn ảnh rồi nháy Insert; kéo ở góc ảnh để chỉnh kích thước cho khỏi méo.\n- GV nhắc HS vừa làm vừa lưu bằng tổ hợp phím Ctrl và S để không mất bài.","hs":"- HS mở được phần mềm, tạo trang chiếu và gõ tiêu đề cho sản phẩm.\n- HS chèn được ảnh từ thư mục tư liệu và chỉnh kích thước ảnh cho cân đối.\n- HS bấm Ctrl và S để lưu bài trong lúc làm."},{"ten":"3. Luyện tập - Trình bày","gv":"- (11 phút) GV cho HS hoàn thiện sản phẩm, lưu vào thư mục mang tên mình rồi trình bày trước nhóm bằng cách bấm phím F5 và dùng phím mũi tên chuyển trang.\n- GV nêu ba tiêu chí nhận xét: nội dung đúng chủ đề, chữ dễ đọc và ảnh hợp nội dung, bài lưu đúng thư mục của mình.\n- Lỗi HS hay mắc và cách xử lí: quên lưu bài nên mất công làm lại, GV nhắc cả lớp cùng lưu khi còn 5 phút; lưu đè lên bài của bạn do chọn nhầm thư mục, GV hướng dẫn đọc lại tên thư mục trước khi nháy Save; chèn ảnh quá to che hết chữ, GV hướng dẫn kéo góc ảnh cho nhỏ lại và đặt ảnh sang một bên.","hs":"- HS hoàn thiện, lưu và trình bày được sản phẩm của mình trước nhóm.\n- HS nhận xét bài của bạn theo ba tiêu chí bằng lời tử tế.\n- HS nhận ra lỗi của mình, lưu bài đúng thư mục và chỉnh lại ảnh cho hợp lí."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV gợi ý: em có thể dùng máy tính để làm thiệp chúc mừng, làm bảng thời gian biểu hoặc giới thiệu một cuốn sách em thích.\n- GV nhắc sản phẩm phải do chính em làm, xin phép bạn trước khi đưa ảnh có mặt bạn vào bài, không đưa họ tên đầy đủ và địa chỉ nhà lên sản phẩm.\n- GV hướng dẫn tắt phần mềm và tắt máy đúng cách, dặn nội dung ôn tập cho tiết sau.","hs":"- HS chia sẻ ý tưởng dùng máy tính giúp mình hoàn thành một việc học tập khác.\n- HS nhắc lại các quy tắc an toàn khi làm và chia sẻ sản phẩm số.\n- HS tắt máy đúng cách, xếp lại ghế và ghi việc cần ôn cho tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) HS hoàn thành sản phẩm số của mình — tờ giới thiệu hoặc bài trình chiếu ngắn — có tiêu đề, vài dòng nội dung và hình minh hoạ; HS lưu bài vào thư mục mang tên mình rồi giới thiệu trước lớp.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV thao tác cho HS xem phần mềm tự gợi ý bố cục và tự soát lỗi chính tả; GV nói rõ đó là gợi ý của máy, có lúc gợi ý không hợp với ý em và máy còn báo sai với tên riêng, nên em phải đọc lại và tự quyết định giữ hay đổi. HS quan sát, chưa tự dùng công cụ này.\n⚠ (Miền 4: An toàn) Sản phẩm phải do chính HS làm ra, gợi ý của máy chỉ để tham khảo; không đưa họ tên đầy đủ, địa chỉ nhà lên sản phẩm; xin phép bạn trước khi đưa ảnh có mặt bạn vào bài; lưu bài vào đúng thư mục của mình.","hs":"- HS hoàn thành và lưu được một sản phẩm số của mình, giới thiệu trước lớp.\n- HS nêu được gợi ý của máy chỉ để tham khảo, người làm phải đọc lại và quyết định."}]},
{"lop":3,"mon":"Tin học","tuan":34,"tiet":34,"bai":"Ôn tập cuối năm học","yccd":"1. Năng lực Tin học (đặc thù):\n- Hệ thống hoá toàn bộ kiến thức, kĩ năng Tin học lớp 3: thông tin, máy tính, Internet, tổ chức thông tin, an toàn số, ứng dụng tin học, giải quyết vấn đề.\n- Vận dụng tổng hợp, tự đánh giá sự tiến bộ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.\n4. Tích hợp\n- Năng lực số 5.4 CB1a: Nhận ra được năng lực số của tôi cần được cải thiện hoặc cập nhật ở đâu: HS làm bài ôn tương tác và tự nhận ra phần kiến thức mình còn chưa chắc.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi tổng ôn: hỏi – đáp nhanh theo các chủ đề đã học.","hs":"- HS tham gia, nhớ lại kiến thức toàn năm."},{"ten":"2. Ôn tập","gv":"- GV hệ thống kiến thức bằng sơ đồ tư duy các chủ đề A–F.","hs":"- HS nhắc lại nội dung trọng tâm từng chủ đề; nêu ví dụ."},{"ten":"3. Luyện tập","gv":"- GV cho HS làm bài luyện tập tổng hợp (trắc nghiệm + thao tác thực hành).","hs":"- HS làm bài, tự đánh giá và đánh giá bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ bài tập tương tác có chấm tự động ôn lại cả năm: gọi tên bộ phận máy tính, sắp thứ tự các bước của một công việc, chọn câu Nếu… thì… đúng với tình huống, chọn cách giữ an toàn thông tin cá nhân; HS nhìn kết quả để tự biết phần nào mình còn hổng.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) HS chọn trong số sản phẩm cả năm — hình vẽ bằng chuột, đoạn văn bản đã gõ, bài trình chiếu — một sản phẩm ưng ý nhất, sửa lại cho hoàn chỉnh và giới thiệu trước lớp mình đã làm được gì trên máy tính trong năm học.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV nhắc lại những lần cả lớp đã thấy máy làm việc thay người trong năm: máy đọc chữ thành tiếng, máy nghe tiếng nói viết thành chữ, ứng dụng đoán tên cây qua ảnh; GV nhấn mạnh máy làm được là do con người dạy cho nó, máy vẫn sai nên người phải kiểm tra lại. HS nghe và nêu ví dụ mình đã thấy.\n⚠ (Miền 4: An toàn) Tự làm hết bài rồi mới xem đáp án, xem để hiểu chứ không chép của bạn; chỉ mở thư mục và sản phẩm của mình, không mở, không sửa, không xoá bài của bạn; hết giờ tắt máy đúng cách rồi mới rời phòng máy.","hs":"- HS làm bài ôn tương tác và tự nhận ra phần kiến thức mình còn chưa chắc.\n- HS hoàn thiện được một sản phẩm số của mình và nói rõ đã sửa chỗ nào."}]},
{"lop":3,"mon":"Tin học","tuan":35,"tiet":35,"bai":"Kiểm tra, đánh giá cuối năm học","yccd":"1. Năng lực Tin học (đặc thù):\n- Đánh giá kết quả học tập cả năm: kiến thức và kĩ năng thực hành Tin học lớp 3.\n- Rèn tính trung thực, tự giác, có trách nhiệm khi làm bài và khi sử dụng máy tính.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- GV: Kiểm tra trước giờ học các máy đã bật được, chuột và bàn phím còn tốt; chia nhóm 2 đến 3 HS một máy, dán số nhóm lên từng máy để HS luân phiên thao tác.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.\n- HS: Tay khô sạch trước khi vào phòng máy, không mang đồ ăn và nước uống vào phòng máy, ngồi đúng tư thế và không tự ý rút dây thiết bị.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV ổn định lớp, chia nhóm 2 đến 3 HS một máy và phổ biến yêu cầu, hình thức kiểm tra cuối năm.\n- GV nêu rõ bài kiểm tra gồm phần trắc nghiệm trên phiếu và phần thực hành trên máy, thời gian làm bài và cách nộp bài.\n- GV nhắc nội quy phòng máy và quy tắc làm bài: ngồi đúng tư thế, tự làm bài, không mở bài của bạn, không nhắc bài cho nhau.","hs":"- HS lắng nghe, về đúng máy theo nhóm và chuẩn bị đồ dùng làm bài.\n- HS nhắc lại hình thức, thời gian làm bài và cách nộp bài.\n- HS nhắc lại nội quy phòng máy và quy tắc làm bài trung thực."},{"ten":"2. Kiểm tra","gv":"- (17 phút) GV phát đề trắc nghiệm gồm các câu về thao tác chuột, các hàng phím, tệp và thư mục, an toàn thông tin và các bước của một công việc.\n- GV giao phần thực hành: tạo một thư mục mang tên em trong thư mục của lớp, tạo một bài trình chiếu hai trang có tiêu đề, vài dòng chữ và một hình, rồi lưu vào thư mục vừa tạo.\n- Lỗi HS hay mắc và cách xử lí: quên lưu bài nên hết giờ chưa có sản phẩm, GV nhắc cả lớp lưu bài khi còn 5 phút; lưu nhầm thư mục, GV hướng dẫn đọc lại tên thư mục trên thanh địa chỉ trước khi nháy Save; bật Caps Lock nên cả dòng ra chữ hoa, GV chỉ đèn báo và hướng dẫn bấm lại phím đó rồi gõ lại.","hs":"- HS làm bài trắc nghiệm trên phiếu một cách trung thực, đúng thời gian.\n- HS thực hiện phần thực hành: tạo thư mục, tạo và lưu bài trình chiếu đúng yêu cầu.\n- HS nhận ra lỗi của mình, lưu lại bài đúng thư mục và sửa chỗ gõ sai."},{"ten":"3. Nhận xét - Đánh giá","gv":"- (8 phút) GV thu phiếu, mở nhanh sản phẩm trên vài máy và chiếu lên cho cả lớp cùng xem.\n- GV nhận xét theo ba tiêu chí: thao tác đúng và nhanh, sản phẩm đủ yêu cầu và lưu đúng chỗ, giữ gìn thiết bị và trật tự trong giờ kiểm tra.\n- GV tuyên dương HS tiến bộ trong cả năm học, động viên những em còn chậm tiếp tục luyện thêm.","hs":"- HS nộp bài đúng giờ và cùng xem sản phẩm của bạn trên máy chiếu.\n- HS lắng nghe nhận xét, tự đối chiếu bài của mình theo ba tiêu chí.\n- HS tự rút kinh nghiệm và nêu điều mình cần luyện thêm."},{"ten":"4. Vận dụng - Dặn dò","gv":"- (5 phút) GV gợi ý những việc HS có thể làm với máy tính trong dịp hè: luyện gõ mười ngón, sắp xếp lại thư mục ảnh của gia đình, làm một tấm thiệp tặng ông bà.\n- GV nhắc quy tắc dùng thiết bị hợp lí trong hè: mỗi lần ngồi máy không quá 30 phút, nghỉ mắt sau 20 phút, không dùng máy trong phòng tối, không cho người lạ biết thông tin riêng.\n- GV hướng dẫn HS tắt máy đúng cách, xếp lại ghế, chuột và bàn phím rồi mới rời phòng máy.","hs":"- HS nêu việc mình định làm với máy tính trong dịp hè.\n- HS nhắc lại quy tắc về thời gian dùng máy và giữ an toàn thông tin.\n- HS tắt máy đúng cách, xếp gọn chỗ ngồi trước khi rời phòng máy."}]}
];
